window.VeilGardeData.files["Sources-VeilGardeAudio"] = {"group":"Sources-VeilGardeAudio","files":[{"path":"Sources/VeilGardeAudio/Acceptance/AudioAcceptance.swift","status":"added","lang":"swift","hunks":[[1,0,1,307]],"header":{"lines":[1,27],"target":"VeilGardeAudio","what":[6,12],"pin":[13,26],"in":null,"out":null,"style":"swift"},"marks":[],"first":876,"scopes":[["S","AudioAcceptanceSettings",null,"public",33,33,[33,68],55,null,-1,0,"a"],["i","init",[],"public",50,50,[50,18],50,null,0,8,"a"],["v","spectrogramProfile",null,"public",52,52,[52,54],52,null,0,8,"a"],["v","options",null,"",53,53,[53,30],53,null,0,8,"a"],["v","phaseZero",null,"",54,54,[54,32],54,null,0,8,"a"],["S","AudioAcceptanceInput",null,"public",57,57,[57,45],69,null,-1,0,"a"],["i","init",["path","segment","kind","clip"],"public",63,63,[63,75],68,null,5,0,"a"],["S","AudioAcceptanceClip",null,"public",71,71,[71,53],119,null,-1,0,"a"],["S","Cut",null,"public",72,72,[72,41],77,null,7,0,"a"],["S","Reencode",null,"public",79,79,[79,46],87,null,7,0,"a"],["S","AudioAcceptanceSummary",null,"public",121,121,[121,56],145,null,-1,0,"a"],["S","AudioAcceptanceReport",null,"public",147,147,[147,55],153,null,-1,0,"a"],["E","AudioAcceptance",null,"public",155,155,[155,28],307,null,-1,0,"a",[]],["f","synthetic",["count","profile"],"public static",157,157,[157,100],162,[156,156],12,0,"a"],["f","run",["_","settings","note","measured"],"public static",164,164,[165,146],266,null,12,0,"a"],["f","summarize",["_","settings"],"public static",268,268,[268,125],306,null,12,0,"a"],["f","median",["_"],"",270,270,[270,45],270,null,15,12,"a"]],"old":"","new":"//\n//  AudioAcceptance.swift\n//  VeilGardeAudio\n//  SPDX-License-Identifier: GPL-3.0-only\n//\n//  WHAT: Whether v1 holds on sound, measured as the image lane measures it: for each admitted clip,\n//        a self-match, a half-duration cut at a random sample offset (its match and the offset it\n//        recovers), an AAC re-encode, a cross match of the cut against the next clip's signature\n//        (the false matches), and on every fourth clip the cut's speed changed by 0.9× and 0.75×\n//        (where v1 is expected to break). Then the kill criterion, stated before the run. Beside\n//        it, measured and not gated: a tile-aligned cut, a gain change, 16-bit requantization,\n//        white noise, both round trips, and each clip's fragility statistics.\n//  PIN:  The acceptance, fixed before the run (ledger decision-142): self-match 100%; the cut\n//        matches (score ≥ 0.75, ≥ 256 bits) with its offset within one tile in at least 60% of\n//        clips; the median AAC score is at least 0.75; some threshold reaches ≥ 80% cut recall at\n//        ≤ 5% cross false matches. Failing any kills v1 on audio. The AAC rate is the profile's, or\n//        the highest the encoder offers below it at the clip's rate, recorded per clip. The fallbacks, named now: a\n//        sub-hop phase search at quarter-hop sample offsets; the hop halved; the floor at −80 dB if\n//        the false-match rule kills; the image lane's own. The cut and the speed changes use the\n//        time-phase search; the re-encode, realigned by its measured lag, the gain, the\n//        requantization and the noise are matched at phase 0, as the JPEG is. With cutSubHop 4 the\n//        cut is also tried with its first quarter, half and three quarters of a hop dropped, the\n//        best score kept, and the cross match gets the same four chances (experiment B). Admission: the\n//        profile's minimum duration, the duration cap and an RMS of at least −40 dBFS. Seeded by\n//        SplitMix64: per clip the cut's start, then the noise seed. Nothing is written but the\n//        report, each clip's row as it is measured, and the codec's transient file.\n//\n\nimport Foundation\nimport VeilGardeCore\nimport VeilWatermark\n\npublic struct AudioAcceptanceSettings: Codable, Sendable, Equatable {\n    public var seed: UInt64 = 0\n    public var profile: String = SpectrogramProfile.music.name\n    public var cutFraction = 0.5\n    public var speeds: [Double] = [0.9, 0.75]\n    /// The speed changes are measured on every n-th clip.\n    public var speedEvery = 4\n    public var gainDB: Double = -6\n    public var noiseSNRDB: Double = 30\n    public var phases: [Int] = MatchOptions.default.phases\n    public var minimumBits = MatchOptions.default.minimumBits\n    public var threshold = MatchOptions.default.threshold\n    /// Tracks are cut into segments this long before sampling; 0 keeps whole files.\n    public var segmentSeconds: Double = 10\n    /// Fractions of a hop the cut is also tried at, the best kept: 1 is the plain search, 4 tries 0, ¼, ½ and ¾ (experiment B).\n    public var cutSubHop = 1\n\n    public init() {}\n\n    public var spectrogramProfile: SpectrogramProfile { SpectrogramProfile.named(profile) ?? .music }\n    var options: MatchOptions { MatchOptions(phases: phases, minimumBits: minimumBits, threshold: threshold) }\n    var phaseZero: MatchOptions { MatchOptions(phases: [0], minimumBits: minimumBits, threshold: threshold) }\n}\n\npublic struct AudioAcceptanceInput: Sendable {\n    public var path: String\n    public var segment: Int\n    public var kind: String\n    public var clip: AudioClip\n\n    public init(path: String, segment: Int, kind: String, clip: AudioClip) {\n        self.path = path\n        self.segment = segment\n        self.kind = kind\n        self.clip = clip\n    }\n}\n\npublic struct AudioAcceptanceClip: Codable, Sendable {\n    public struct Cut: Codable, Sendable {\n        public var startSample: Int\n        public var length: Int\n        public var expectedColumn: Int\n        public var seconds: Double\n    }\n\n    public struct Reencode: Codable, Sendable {\n        public var match: MatchResult\n        public var lagSamples: Int\n        public var lengthDelta: Int\n        /// The profile's rate, the one the encoder offered and was set to, and the stream's measured rate.\n        public var requestedKilobitsPerSecond: Int\n        public var usedKilobitsPerSecond: Int\n        public var kilobitsPerSecond: Double\n    }\n\n    public var path: String\n    public var segment: Int\n    public var kind: String\n    public var nativeRate: Double\n    public var channels: Int\n    public var seconds: Double\n    public var frames: Int\n    public var rmsDBFS: Double\n    public var signedBits: Int\n    public var balance: [Double]\n    public var floorShare: Double\n    public var frMean: Double\n    public var frSpread: Double\n    public var selfMatch: MatchResult\n    public var cut: Cut\n    public var cutMatch: MatchResult\n    /// Which fraction of a hop won the cut's search: 0 of cutSubHop when the plain cut did.\n    public var cutSubHopOffset: Int\n    /// The recovered column's distance from the truth, in tiles (the larger of time and frequency).\n    public var cutOffsetError: Double\n    public var alignedCutMatch: MatchResult\n    public var reencode: Reencode\n    public var cross: MatchResult\n    public var speed: [String: MatchResult]\n    public var gain: MatchResult\n    public var pcm16: MatchResult\n    public var noise: MatchResult\n    public var roundTripExact: AudioRoundTripMetrics\n    public var roundTripImage: AudioRoundTripMetrics\n    public var elapsed: Double\n}\n\npublic struct AudioAcceptanceSummary: Codable, Sendable {\n    public var clips: Int\n    public var selfMatchRate: Double\n    public var cutMatchRate: Double\n    public var reencodeMedianScore: Double\n    public var crossFalseMatchRate: Double\n    public var crossMedianScore: Double\n    /// The best threshold for cut recall ≥ 80%, and its false-match rate.\n    public var operatingThreshold: Double?\n    public var operatingRecall: Double?\n    public var operatingFalseMatchRate: Double?\n    public var bitBalance: [Double]\n    public var speedMatchRate: [String: Double]\n    public var alignedCutMatchRate: Double\n    public var gainMedianScore: Double\n    public var pcm16MedianScore: Double\n    public var noiseMedianScore: Double\n    public var reencodeLagZeroRate: Double\n    public var offsetYNonZero: Int\n    public var degenerateClips: Int\n    public var exactSNRMedianDB: Double\n    public var imageSNRMedianDB: Double\n    public var killed: Bool\n    public var reasons: [String]\n}\n\npublic struct AudioAcceptanceReport: Codable, Sendable {\n    public var date: Date\n    public var settings: AudioAcceptanceSettings\n    public var profile: SpectrogramProfile.Record\n    public var summary: AudioAcceptanceSummary\n    public var clips: [AudioAcceptanceClip]\n}\n\npublic enum AudioAcceptance {\n    /// `count` music-like clips, seeds 1…count, 12 s at the profile's rate.\n    public static func synthetic(count: Int, profile: SpectrogramProfile) -> [AudioAcceptanceInput] {\n        (1...max(1, count)).map { seed in\n            AudioAcceptanceInput(path: \"synthetic:musicLike:\\(seed)\", segment: 0, kind: \"synthetic\",\n                                 clip: SyntheticClips.musicLike(seed: UInt64(seed), seconds: 12, sampleRate: profile.sampleRate))\n        }\n    }\n\n    public static func run(_ inputs: [AudioAcceptanceInput], settings: AudioAcceptanceSettings = AudioAcceptanceSettings(),\n                           note: (String) -> Void = { _ in }, measured: (AudioAcceptanceClip) -> Void = { _ in }) throws -> AudioAcceptanceReport {\n        var rng = SplitMix64(seed: settings.seed)\n        let profile = settings.spectrogramProfile\n        let options = settings.options, phaseZero = settings.phaseZero\n        // Pass 1: every signature (the cross matches need the next clip's).\n        var admitted: [(input: AudioAcceptanceInput, image: SpectrogramImage, signature: WatermarkSignature, grid: FragilityGrid)] = []\n        for input in inputs {\n            let clip = input.clip\n            let label = input.kind == \"synthetic\" ? input.path : \"\\(URL(fileURLWithPath: input.path).lastPathComponent)#\\(input.segment)\"\n            if clip.seconds < profile.minimumSeconds {\n                note(String(format: \"accept: skipped %@: %.1f s, under the %@ profile's %.0f s\", label, clip.seconds, profile.name, profile.minimumSeconds)); continue\n            }\n            if clip.seconds > SpectrogramProfile.maximumSeconds { note(String(format: \"accept: skipped %@: %.0f s, over the cap\", label, clip.seconds)); continue }\n            let level = clip.rmsDBFS\n            if level < SpectrogramProfile.minimumRMSDBFS { note(String(format: \"accept: skipped %@: %.1f dBFS, under −40\", label, level)); continue }\n            let image = try AudioWatermark.picture(clip, profile: profile)\n            // One fragility read: the signature is built from it exactly as Watermark.sign builds it (AudioWatermarkTests).\n            let grid = try AudioWatermark.fragility(image)\n            let signature = WatermarkSignature(grid: TileCodeGrid(grid))\n            admitted.append((input, image, signature, grid))\n            if admitted.count % 10 == 0 { note(\"accept: signed \\(admitted.count) of \\(inputs.count)\") }\n        }\n        note(\"accept: signed \\(admitted.count) clips (\\(inputs.count - admitted.count) skipped); matching\")\n        var rows: [AudioAcceptanceClip] = []\n        for (i, entry) in admitted.enumerated() {\n            let started = Date()\n            let clip = entry.input.clip, image = entry.image, signature = entry.signature\n            let selfMatch = try AudioWatermark.match(image, against: signature, options: phaseZero).result\n            // A cut of half the duration, at a random native-sample offset; with cutSubHop over 1, also with its first fractions\n            // of a hop dropped, the best score kept (experiment B), and the cross match gets the same chances.\n            let cutLength = max(1, Int(Double(clip.frames) * settings.cutFraction))\n            let start = rng.index(max(1, clip.frames - cutLength + 1))\n            let cutClip = AudioTransforms.cut(clip, startSample: start, length: cutLength)\n            let subHop = max(1, settings.cutSubHop)\n            var cutMatch = MatchResult.none, cutCodesTried: [[(px: Int, py: Int, codes: TileCodeGrid)]] = [], expected = 0, cutSubHopOffset = 0\n            for q in 0..<subHop {\n                let delta = Int((Double(q) / Double(subHop) * Double(profile.hop) * clip.sampleRate / profile.sampleRate).rounded())\n                let shifted = q == 0 ? cutClip : AudioTransforms.cut(cutClip, startSample: delta, length: cutClip.frames - delta)\n                let codes = try AudioWatermark.phaseCodes(try AudioWatermark.picture(shifted, profile: profile), phases: settings.phases)\n                cutCodesTried.append(codes)\n                let m = Watermark.match(codes: codes, against: signature, options: options)\n                if q == 0 || m.score > cutMatch.score {\n                    cutMatch = m\n                    cutSubHopOffset = q\n                    expected = AudioWatermark.expectedColumn(startSample: start + delta, nativeRate: clip.sampleRate, profile: profile)\n                }\n            }\n            let cutError = max(Double(abs(cutMatch.pixelX - expected)) / Double(WarpConstants.tileSize), Double(abs(cutMatch.offsetY)))\n            // The same cut moved to the nearest tile column boundary, matched at phase 0: the picture-equality claim alone.\n            let tileNative = Double(profile.hop * WarpConstants.tileSize) * clip.sampleRate / profile.sampleRate\n            let alignedStart = max(0, min(Int((Double(start) / tileNative).rounded() * tileNative), clip.frames - cutLength))\n            let alignedCut = AudioTransforms.cut(clip, startSample: alignedStart, length: cutLength)\n            let alignedMatch = try AudioWatermark.match(try AudioWatermark.picture(alignedCut, profile: profile), against: signature, options: phaseZero).result\n            // The re-encode, realigned by its measured lag, matched at phase 0 like the JPEG.\n            let aac = try AudioConverting.aacRoundTrip(clip, kilobitsPerSecond: profile.aacKilobitsPerSecond)\n            let lag = SignalAlignment.lag(of: aac.clip.mono, against: clip.mono)\n            let realigned = AudioClip(sampleRate: clip.sampleRate, mono: SignalAlignment.aligned(aac.clip.mono, by: lag, length: clip.frames))\n            let reencodeMatch = try AudioWatermark.match(try AudioWatermark.picture(realigned, profile: profile), against: signature, options: phaseZero).result\n            let other = admitted[(i + 1) % admitted.count].signature\n            var cross = MatchResult.none\n            for (q, codes) in cutCodesTried.enumerated() {\n                let m = Watermark.match(codes: codes, against: other, options: options)\n                if q == 0 || m.score > cross.score { cross = m }\n            }\n            var speed: [String: MatchResult] = [:]\n            for factor in settings.speeds where i % max(1, settings.speedEvery) == 0 {\n                let changed = try AudioConverting.speedChanged(cutClip, by: factor)\n                speed[String(format: \"%.2f\", factor)] = Watermark.match(codes: try AudioWatermark.phaseCodes(try AudioWatermark.picture(changed, profile: profile), phases: settings.phases),\n                                                                       against: signature, options: options)\n            }\n            let gain = try AudioWatermark.match(try AudioWatermark.picture(AudioTransforms.gained(clip, dB: settings.gainDB), profile: profile), against: signature, options: phaseZero).result\n            let pcm16 = try AudioWatermark.match(try AudioWatermark.picture(AudioTransforms.requantized16Bit(clip), profile: profile), against: signature, options: phaseZero).result\n            let noiseSeed = rng.next()\n            let noise = try AudioWatermark.match(try AudioWatermark.picture(AudioTransforms.withWhiteNoise(clip, snrDB: settings.noiseSNRDB, seed: noiseSeed), profile: profile),\n                                                 against: signature, options: phaseZero).result\n            let signal = try AnalysisSignal(clip, profile: profile)\n            let exact = AudioRoundTrip.exact(signal).metrics\n            let viaImage = AudioRoundTrip.throughImage(signal).metrics\n            var frMean = 0.0\n            for v in entry.grid.values { frMean += Double(v) }\n            frMean /= Double(max(1, entry.grid.values.count))\n            var frVariance = 0.0\n            for v in entry.grid.values { frVariance += (Double(v) - frMean) * (Double(v) - frMean) }\n            frVariance /= Double(max(1, entry.grid.values.count))\n            let codes = signature.tileCodes\n            rows.append(AudioAcceptanceClip(\n                path: entry.input.path, segment: entry.input.segment, kind: entry.input.kind, nativeRate: clip.sampleRate, channels: clip.channelCount,\n                seconds: clip.seconds, frames: image.width, rmsDBFS: clip.rmsDBFS, signedBits: signature.measuredBits, balance: codes.balance,\n                floorShare: image.floorShare, frMean: frMean, frSpread: frVariance.squareRoot(), selfMatch: selfMatch,\n                cut: .init(startSample: start, length: cutLength, expectedColumn: expected, seconds: Double(start) / clip.sampleRate),\n                cutMatch: cutMatch, cutSubHopOffset: cutSubHopOffset, cutOffsetError: cutError, alignedCutMatch: alignedMatch,\n                reencode: .init(match: reencodeMatch, lagSamples: lag, lengthDelta: aac.lengthDelta, requestedKilobitsPerSecond: aac.requestedKilobitsPerSecond,\n                                usedKilobitsPerSecond: aac.usedKilobitsPerSecond, kilobitsPerSecond: aac.kilobitsPerSecond),\n                cross: cross, speed: speed, gain: gain, pcm16: pcm16, noise: noise, roundTripExact: exact, roundTripImage: viaImage,\n                elapsed: Date().timeIntervalSince(started)))\n            measured(rows[rows.count - 1])\n            let label = entry.input.kind == \"synthetic\" ? entry.input.path : \"\\(URL(fileURLWithPath: entry.input.path).lastPathComponent)#\\(entry.input.segment)\"\n            note(String(format: \"accept %d/%d %@: self %.3f, cut %.3f (%d bits, off by %.2f tiles), aac %.3f (lag %d), cross %.3f, %.0fs\", i + 1, admitted.count, label,\n                        selfMatch.score, cutMatch.score, cutMatch.bitsCompared, cutError, reencodeMatch.score, lag, cross.score, rows[rows.count - 1].elapsed))\n        }\n        return AudioAcceptanceReport(date: Date(), settings: settings, profile: profile.record, summary: summarize(rows, settings: settings), clips: rows)\n    }\n\n    public static func summarize(_ rows: [AudioAcceptanceClip], settings: AudioAcceptanceSettings) -> AudioAcceptanceSummary {\n        let n = Double(max(1, rows.count))\n        func median(_ v: [Double]) -> Double { v.isEmpty ? .nan : v.sorted()[v.count / 2] }\n        let selfOK = rows.filter { $0.selfMatch.matched && $0.selfMatch.offsetX == 0 && $0.selfMatch.offsetY == 0 && $0.selfMatch.score == 1 }.count\n        let cutOK = rows.filter { $0.cutMatch.matched && $0.cutOffsetError <= 1 }.count\n        let crossFalse = rows.filter { $0.cross.matched }.count\n        // The operating point: the threshold with cut recall ≥ 80% and the fewest false matches.\n        var op: (t: Double, recall: Double, fpr: Double)? = nil\n        for k in 50...100 {\n            let t = Double(k) / 100\n            let recall = Double(rows.filter { $0.cutMatch.score >= t && $0.cutMatch.bitsCompared >= settings.minimumBits && $0.cutOffsetError <= 1 }.count) / n\n            let fpr = Double(rows.filter { $0.cross.score >= t && $0.cross.bitsCompared >= settings.minimumBits }.count) / n\n            if recall >= 0.80, op == nil || fpr < op!.fpr || (fpr == op!.fpr && t > op!.t) { op = (t, recall, fpr) }\n        }\n        var balance = [Double](repeating: 0, count: 4)\n        for k in 0..<4 { balance[k] = median(rows.map { $0.balance[k] }.filter(\\.isFinite)) }\n        var speedRate: [String: Double] = [:]\n        for key in Set(rows.flatMap { $0.speed.keys }) {\n            let measured = rows.filter { $0.speed[key] != nil }\n            speedRate[key] = Double(measured.filter { $0.speed[key]?.matched == true }.count) / Double(max(1, measured.count))\n        }\n        let cutRate = Double(cutOK) / n, reencodeMedian = median(rows.map(\\.reencode.match.score))\n        var reasons: [String] = []\n        if cutRate < 0.60 { reasons.append(String(format: \"the cut matched with its offset in %.0f%% of clips, under 60%%\", cutRate * 100)) }\n        if reencodeMedian < 0.75 { reasons.append(String(format: \"the median AAC re-encode score is %.3f, under 0.75\", reencodeMedian)) }\n        if let op, op.fpr > 0.05 { reasons.append(String(format: \"at 80%% cut recall the fewest false matches are %.1f%%, over 5%%\", op.fpr * 100)) }\n        if op == nil { reasons.append(\"no threshold reaches 80% cut recall\") }\n        let degenerate = rows.filter { $0.floorShare > 0.9 || $0.balance.allSatisfy { $0 < 0.05 } }.count\n        return AudioAcceptanceSummary(\n            clips: rows.count, selfMatchRate: Double(selfOK) / n, cutMatchRate: cutRate, reencodeMedianScore: reencodeMedian,\n            crossFalseMatchRate: Double(crossFalse) / n, crossMedianScore: median(rows.map(\\.cross.score)),\n            operatingThreshold: op?.t, operatingRecall: op?.recall, operatingFalseMatchRate: op?.fpr, bitBalance: balance, speedMatchRate: speedRate,\n            alignedCutMatchRate: Double(rows.filter(\\.alignedCutMatch.matched).count) / n,\n            gainMedianScore: median(rows.map(\\.gain.score)), pcm16MedianScore: median(rows.map(\\.pcm16.score)), noiseMedianScore: median(rows.map(\\.noise.score)),\n            reencodeLagZeroRate: Double(rows.filter { $0.reencode.lagSamples == 0 }.count) / n,\n            offsetYNonZero: rows.filter { $0.cutMatch.matched && $0.cutMatch.offsetY != 0 }.count, degenerateClips: degenerate,\n            exactSNRMedianDB: median(rows.map(\\.roundTripExact.snrDB)), imageSNRMedianDB: median(rows.map(\\.roundTripImage.snrDB)),\n            killed: !reasons.isEmpty, reasons: reasons)\n    }\n}\n"},{"path":"Sources/VeilGardeAudio/Acceptance/AudioAcceptanceSample.swift","status":"added","lang":"swift","hunks":[[1,0,1,104]],"header":{"lines":[1,14],"target":"VeilGardeAudio","what":[6,8],"pin":[9,13],"in":null,"out":null,"style":"swift"},"marks":[],"first":893,"scopes":[["E","AudioAcceptanceSample",null,"public",19,19,[19,34],104,null,-1,0,"a",[]],["S","Item",null,"public",20,20,[20,53],35,null,0,0,"a"],["i","init",["url","segment","startSeconds","durationSeconds"],"public",27,27,[27,92],32,null,1,0,"a"],["v","label",null,"public",34,34,[34,33],34,null,1,8,"a"],["f","files",["in"],"public static",39,39,[39,60],57,[37,38],0,0,"a"],["f","segments",["total","segment"],"public static",60,60,[60,71],60,[59,59],0,8,"a"],["f","items",["for","segmentSeconds"],"public static",63,63,[63,89],76,[62,62],0,0,"a"],["f","sample",["_","n","seed"],"public static",79,79,[79,79],84,[78,78],0,0,"a"],["f","load",["_","note"],"public static",87,87,[87,122],103,[86,86],0,0,"a"]],"old":"","new":"//\n//  AudioAcceptanceSample.swift\n//  VeilGardeAudio\n//  SPDX-License-Identifier: GPL-3.0-only\n//\n//  WHAT: The clips an acceptance runs on: the audio files an argument names (a folder searched\n//        recursively, a text file of paths, or one file), each cut into consecutive segments of a\n//        fixed length, a seeded sample of them, and their loading.\n//  PIN:  Segments start at 0 and run back to back; the last partial one is dropped; a track\n//        shorter than one segment yields none. The sample is SplitMix64(seed).permutation's first n,\n//        kept in folder order, so the cross match's \"next clip\" is usually a neighbouring segment of\n//        the same track: the hardest false-match case, said in the report. Each file is decoded once\n//        for all its sampled segments.\n//\n\nimport Foundation\nimport VeilGardeCore\n\npublic enum AudioAcceptanceSample {\n    public struct Item: Sendable, Equatable, Codable {\n        public var url: URL\n        public var segment: Int\n        public var startSeconds: Double\n        /// nil: the whole file.\n        public var durationSeconds: Double?\n\n        public init(url: URL, segment: Int, startSeconds: Double, durationSeconds: Double?) {\n            self.url = url\n            self.segment = segment\n            self.startSeconds = startSeconds\n            self.durationSeconds = durationSeconds\n        }\n\n        public var label: String { durationSeconds == nil ? url.lastPathComponent : \"\\(url.lastPathComponent)#\\(segment)\" }\n    }\n\n    /// The audio files `input` names: a text file of paths (`#` comments), a folder (recursive,\n    /// sorted by path, exFAT sidecars skipped) or one file.\n    public static func files(in input: URL) throws -> [URL] {\n        if input.pathExtension.lowercased() == \"txt\" {\n            let text = try String(contentsOf: input, encoding: .utf8)\n            return text.split(separator: \"\\n\").map { $0.trimmingCharacters(in: .whitespaces) }.filter { !$0.isEmpty && !$0.hasPrefix(\"#\") }\n                .map { URL(fileURLWithPath: ($0 as NSString).expandingTildeInPath) }\n        }\n        var isDirectory: ObjCBool = false\n        guard FileManager.default.fileExists(atPath: input.path, isDirectory: &isDirectory) else {\n            throw VeilGardeFailure.missing(\"no audio file or folder at \\(input.path)\")\n        }\n        guard isDirectory.boolValue else { return [input] }\n        var out: [URL] = []\n        let walker = FileManager.default.enumerator(at: input, includingPropertiesForKeys: [.isRegularFileKey], options: [.skipsHiddenFiles])\n        while let next = walker?.nextObject() as? URL {\n            guard !next.lastPathComponent.hasPrefix(\"._\"), AudioFiles.extensions.contains(next.pathExtension.lowercased()) else { continue }\n            out.append(next)\n        }\n        return out.sorted { $0.path < $1.path }\n    }\n\n    /// How many segments of `segment` seconds a track of `total` seconds holds.\n    public static func segments(total: Double, segment: Double) -> Int { segment > 0 && total > 0 ? Int(total / segment) : 0 }\n\n    /// Every segment of every file, in file order; `segmentSeconds` nil or 0 keeps whole files.\n    public static func items(for files: [URL], segmentSeconds: Double?) throws -> [Item] {\n        var out: [Item] = []\n        for url in files {\n            guard let segment = segmentSeconds, segment > 0 else {\n                out.append(Item(url: url, segment: 0, startSeconds: 0, durationSeconds: nil))\n                continue\n            }\n            let info = try AudioFiles.info(of: url)\n            for k in 0..<segments(total: info.seconds, segment: segment) {\n                out.append(Item(url: url, segment: k, startSeconds: Double(k) * segment, durationSeconds: segment))\n            }\n        }\n        return out\n    }\n\n    /// At most `n` of `items`, chosen by the seed, in the items' order.\n    public static func sample(_ items: [Item], n: Int, seed: UInt64) -> [Item] {\n        guard items.count > n else { return items }\n        var rng = SplitMix64(seed: seed)\n        let picked = Set(rng.permutation(items.count).prefix(max(0, n)))\n        return items.enumerated().filter { picked.contains($0.offset) }.map(\\.element)\n    }\n\n    /// The items' clips, each file decoded once.\n    public static func load(_ items: [Item], note: (String) -> Void = { _ in }) throws -> [(item: Item, clip: AudioClip)] {\n        var out: [(Item, AudioClip)] = []\n        var current: (URL, AudioClip)? = nil\n        for item in items {\n            if current?.0 != item.url {\n                current = (item.url, try AudioFiles.read(item.url))\n                note(\"accept: decoded \\(item.url.lastPathComponent)\")\n            }\n            guard let whole = current?.1 else { continue }\n            if let duration = item.durationSeconds {\n                out.append((item, AudioTransforms.cut(whole, startSample: Int(item.startSeconds * whole.sampleRate), length: Int(duration * whole.sampleRate))))\n            } else {\n                out.append((item, whole))\n            }\n        }\n        return out\n    }\n}\n"},{"path":"Sources/VeilGardeAudio/Acceptance/SyntheticClips.swift","status":"added","lang":"swift","hunks":[[1,0,1,124]],"header":{"lines":[1,15],"target":"VeilGardeAudio","what":[6,9],"pin":[10,14],"in":null,"out":null,"style":"swift"},"marks":[],"first":902,"scopes":[["E","SyntheticClips",null,"public",20,20,[20,27],124,null,-1,0,"a",[]],["E","Kind",null,"public",21,21,[21,62],21,null,0,8,"a",[]],["f","make",["_","seed","seconds","sampleRate","peak"],"public static",23,23,[23,140],31,null,0,0,"a"],["f","musicLike",["seed","seconds","sampleRate","peak"],"public static",33,33,[33,131],80,null,0,0,"a"],["f","tone",["frequency","amplitude","seconds","sampleRate"],"public static",82,82,[82,116],85,null,0,0,"a"],["f","whiteNoise",["seed","rmsDBFS","seconds","sampleRate"],"public static",87,87,[87,115],92,null,0,0,"a"],["f","clicks",["seed","seconds","sampleRate","every"],"public static",96,96,[96,116],106,[94,95],0,0,"a"],["f","silence",["seconds","sampleRate"],"public static",108,108,[108,81],110,null,0,0,"a"],["f","pcm16SHA256",["_"],"public static",113,113,[113,64],123,[112,112],0,0,"a"]],"old":"","new":"//\n//  SyntheticClips.swift\n//  VeilGardeAudio\n//  SPDX-License-Identifier: GPL-3.0-only\n//\n//  WHAT: Seeded signals for the tests, the examples and `audio accept --synthetic`: a music-like\n//        mix of harmonic voices with notes, attacks and decays, one exponential chirp, Gaussian\n//        bursts and a quiet noise bed; white noise; a tone; silence; a click train. And a hash of a clip's 16-bit\n//        samples, so a drift in the generator is told from a drift in the carrier.\n//  PIN:  Every draw comes from SplitMix64(seed) in one fixed order; sin, exp and pow are the\n//        platform's, so a pin holds on one machine and says so. The music-like clip is six voices\n//        of five partials at 1/k^1.2 over 12-TET notes of 0.25 to 1 s with 5 ms attacks and a 0.4 s\n//        decay, a 200 → 4000 Hz chirp at −24 dBFS, bursts of 20–80 ms at −20 dBFS about every 1.5 s\n//        and a −60 dBFS Gaussian bed, the whole peak-normalised.\n//\n\nimport Foundation\nimport VeilGardeCore\n\npublic enum SyntheticClips {\n    public enum Kind: String, Codable, Sendable, CaseIterable { case musicLike, whiteNoise, tone, silence, clicks }\n\n    public static func make(_ kind: Kind, seed: UInt64, seconds: Double = 12, sampleRate: Double = 44_100, peak: Double = 0.5) -> AudioClip {\n        switch kind {\n        case .musicLike: return musicLike(seed: seed, seconds: seconds, sampleRate: sampleRate, peak: peak)\n        case .whiteNoise: return whiteNoise(seed: seed, rmsDBFS: -20, seconds: seconds, sampleRate: sampleRate)\n        case .tone: return tone(frequency: 440, amplitude: peak, seconds: seconds, sampleRate: sampleRate)\n        case .silence: return silence(seconds: seconds, sampleRate: sampleRate)\n        case .clicks: return clicks(seed: seed, seconds: seconds, sampleRate: sampleRate)\n        }\n    }\n\n    public static func musicLike(seed: UInt64, seconds: Double = 12, sampleRate: Double = 44_100, peak: Double = 0.5) -> AudioClip {\n        let n = Int(seconds * sampleRate)\n        var out = [Double](repeating: 0, count: n)\n        var rng = SplitMix64(seed: seed)\n        let durations = [0.25, 0.5, 0.75, 1.0]\n        let attack = max(1, Int(0.005 * sampleRate))\n        for voice in 0..<6 {\n            let base = 45.0 + 7.0 * Double(voice)\n            var t = 0\n            while t < n {\n                let length = min(n - t, Int(durations[rng.index(durations.count)] * sampleRate))\n                let midi = base + Double(rng.index(25)) - 12\n                let f0 = 440 * pow(2, (midi - 69) / 12)\n                let amplitude = 0.08 + 0.08 * rng.unit()\n                let phase0 = rng.unit() * 2 * Double.pi\n                for i in 0..<length {\n                    let time = Double(i) / sampleRate\n                    let envelope = (i < attack ? Double(i) / Double(attack) : 1) * exp(-time / 0.4)\n                    var s = 0.0\n                    for k in 1...5 {\n                        let fk = f0 * Double(k)\n                        if fk < sampleRate / 2 { s += sin(2 * Double.pi * fk * time + phase0 * Double(k)) / pow(Double(k), 1.2) }\n                    }\n                    out[t + i] += amplitude * envelope * s\n                }\n                t += max(1, length)\n            }\n        }\n        let chirpAmplitude = pow(10, -24.0 / 20) * 2.0.squareRoot()\n        let ratio = 20.0, f0 = 200.0\n        for i in 0..<n {\n            let tau = Double(i) / Double(max(1, n - 1))\n            let phase = 2 * Double.pi * f0 * seconds * (pow(ratio, tau) - 1) / log(ratio)\n            out[i] += chirpAmplitude * sin(phase)\n        }\n        let burstRMS = pow(10, -20.0 / 20)\n        var position = Int(0.3 * sampleRate)\n        while position < n {\n            let length = Int((0.02 + 0.06 * rng.unit()) * sampleRate)\n            for i in position..<min(n, position + length) { out[i] += burstRMS * AudioTransforms.gaussian(&rng) }\n            position += Int((1.0 + rng.unit()) * sampleRate)\n        }\n        let bed = pow(10, -60.0 / 20)\n        for i in 0..<n { out[i] += bed * AudioTransforms.gaussian(&rng) }\n        let most = out.reduce(0) { max($0, abs($1)) }\n        let scale = most > 0 ? peak / most : 1\n        return AudioClip(sampleRate: sampleRate, mono: out.map { Float($0 * scale) })\n    }\n\n    public static func tone(frequency: Double, amplitude: Double, seconds: Double, sampleRate: Double) -> AudioClip {\n        let n = Int(seconds * sampleRate)\n        return AudioClip(sampleRate: sampleRate, mono: (0..<n).map { Float(amplitude * sin(2 * Double.pi * frequency * Double($0) / sampleRate)) })\n    }\n\n    public static func whiteNoise(seed: UInt64, rmsDBFS: Double, seconds: Double, sampleRate: Double) -> AudioClip {\n        var rng = SplitMix64(seed: seed)\n        let rms = pow(10, rmsDBFS / 20)\n        let n = Int(seconds * sampleRate)\n        return AudioClip(sampleRate: sampleRate, mono: (0..<n).map { _ in Float(rms * AudioTransforms.gaussian(&rng)) })\n    }\n\n    /// A click every quarter second from t = 0: a 5 ms burst of Gaussian noise at −12 dBFS over a −60 dBFS bed. The sharpest\n    /// time grid the study can be handed, added on 2026-11-08 after the music-like control was judged, as a labelled extra.\n    public static func clicks(seed: UInt64, seconds: Double, sampleRate: Double, every: Double = 0.25) -> AudioClip {\n        var rng = SplitMix64(seed: seed)\n        let n = Int(seconds * sampleRate), burst = Int(0.005 * sampleRate), bed = pow(10, -60.0 / 20), level = pow(10, -12.0 / 20)\n        var out = (0..<n).map { _ in bed * AudioTransforms.gaussian(&rng) }\n        var position = 0.0\n        while Int(position) < n {\n            for i in Int(position)..<min(n, Int(position) + burst) { out[i] += level * AudioTransforms.gaussian(&rng) }\n            position += every * sampleRate\n        }\n        return AudioClip(sampleRate: sampleRate, mono: out.map { Float(min(1, max(-1, $0))) })\n    }\n\n    public static func silence(seconds: Double, sampleRate: Double) -> AudioClip {\n        AudioClip(sampleRate: sampleRate, mono: [Float](repeating: 0, count: Int(seconds * sampleRate)))\n    }\n\n    /// The SHA-256 of the clip's channels as little-endian 16-bit samples, in channel order.\n    public static func pcm16SHA256(_ clip: AudioClip) -> String {\n        var data = Data()\n        data.reserveCapacity(clip.frames * clip.channelCount * 2)\n        for channel in clip.channels {\n            for x in channel {\n                let v = Int16(max(-32768, min(32767, (Double(x) * 32767).rounded())))\n                withUnsafeBytes(of: v.littleEndian) { data.append(contentsOf: $0) }\n            }\n        }\n        return ContentHash.sha256Hex(data)\n    }\n}\n"},{"path":"Sources/VeilGardeAudio/Audio/AudioClip.swift","status":"added","lang":"swift","hunks":[[1,0,1,72]],"header":{"lines":[1,13],"target":"VeilGardeAudio","what":[6,8],"pin":[9,12],"in":null,"out":null,"style":"swift"},"marks":[],"first":911,"scopes":[["S","AudioClip",null,"public",18,18,[18,45],72,null,-1,0,"a"],["i","init",["sampleRate","channels"],"public",23,23,[23,64],29,null,0,0,"a"],["i","init",["sampleRate","mono"],"public",31,31,[31,51],34,null,0,0,"a"],["i","init",["validated","channels"],"",37,37,[37,60],40,[36,36],0,0,"a"],["v","channelCount",null,"public",42,42,[42,33],42,null,0,8,"a"],["v","frames",null,"public",43,43,[43,27],43,null,0,8,"a"],["v","seconds",null,"public",44,44,[44,31],44,null,0,8,"a"],["v","mono",null,"public",47,47,[47,29],58,[46,46],0,0,"a"],["v","peak",null,"public",61,61,[61,27],61,[60,60],0,8,"a"],["v","rmsDBFS",null,"public",64,64,[64,31],64,[63,63],0,8,"a"],["f","rmsDBFS",["_"],"public static",66,66,[66,61],71,null,0,0,"a"]],"old":"","new":"//\n//  AudioClip.swift\n//  VeilGardeAudio\n//  SPDX-License-Identifier: GPL-3.0-only\n//\n//  WHAT: A decoded clip as the carrier holds it: its native sample rate and its channels as Float\n//        samples, deinterleaved; its length, its peak and its level; and the mixdown every analysis\n//        starts from.\n//  PIN:  The mixdown is the per-sample mean over the channels, accumulated in Double and rounded to\n//        Float once. Nothing here resamples: a clip keeps its native rate until an analysis signal\n//        is made from it (AnalysisSignal), so every transform the acceptance applies acts on the\n//        clip as a platform would act on the file.\n//\n\nimport Foundation\nimport VeilGardeCore\n\npublic struct AudioClip: Sendable, Equatable {\n    public var sampleRate: Double\n    /// Deinterleaved, one array per channel, all the same length.\n    public var channels: [[Float]]\n\n    public init(sampleRate: Double, channels: [[Float]]) throws {\n        guard sampleRate > 0 else { throw VeilGardeFailure.data(\"a clip needs a positive sample rate, not \\(sampleRate)\") }\n        guard let first = channels.first else { throw VeilGardeFailure.data(\"a clip needs at least one channel\") }\n        guard channels.allSatisfy({ $0.count == first.count }) else { throw VeilGardeFailure.data(\"a clip's channels must be equally long\") }\n        self.sampleRate = sampleRate\n        self.channels = channels\n    }\n\n    public init(sampleRate: Double, mono: [Float]) {\n        self.sampleRate = sampleRate\n        self.channels = [mono]\n    }\n\n    /// For callers that already hold equal-length channels of a valid clip.\n    init(validated sampleRate: Double, channels: [[Float]]) {\n        self.sampleRate = sampleRate\n        self.channels = channels\n    }\n\n    public var channelCount: Int { channels.count }\n    public var frames: Int { channels.first?.count ?? 0 }\n    public var seconds: Double { Double(frames) / sampleRate }\n\n    /// The mixdown: the per-sample mean over the channels, in Double, rounded once.\n    public var mono: [Float] {\n        if channels.count == 1 { return channels[0] }\n        let n = frames\n        var out = [Float](repeating: 0, count: n)\n        let scale = 1.0 / Double(channels.count)\n        for i in 0..<n {\n            var sum = 0.0\n            for channel in channels { sum += Double(channel[i]) }\n            out[i] = Float(sum * scale)\n        }\n        return out\n    }\n\n    /// The largest absolute sample over every channel.\n    public var peak: Float { channels.reduce(0) { most, channel in channel.reduce(most) { max($0, abs($1)) } } }\n\n    /// The mixdown's level in dBFS (an RMS of 1 is 0 dBFS); −infinity for silence.\n    public var rmsDBFS: Double { AudioClip.rmsDBFS(mono) }\n\n    public static func rmsDBFS(_ samples: [Float]) -> Double {\n        var sum = 0.0\n        for x in samples { sum += Double(x) * Double(x) }\n        guard !samples.isEmpty, sum > 0 else { return -.infinity }\n        return 10 * log10(sum / Double(samples.count))\n    }\n}\n"},{"path":"Sources/VeilGardeAudio/Audio/AudioConverting.swift","status":"added","lang":"swift","hunks":[[1,0,1,143]],"header":{"lines":[1,20],"target":"VeilGardeAudio","what":[6,8],"pin":[9,19],"in":null,"out":null,"style":"swift"},"marks":[],"first":922,"scopes":[["E","AudioConverting",null,"public",26,26,[26,28],143,null,-1,0,"a",[]],["f","resampled",["_","from","to"],"public static",28,28,[28,94],73,[27,27],0,0,"a"],["f","speedChanged",["_","by"],"public static",77,77,[77,94],81,[75,76],0,0,"a"],["S","AACRoundTrip",null,"public",83,83,[83,41],93,null,0,0,"a"],["f","aacRoundTrip",["_","kilobitsPerSecond"],"public static",96,96,[96,112],121,[95,95],0,0,"a"],["f","aacBitRates",["sampleRate","channels"],"public static",124,124,[124,79],131,[123,123],0,0,"a"],["f","audioBytes",["_"],"static",134,134,[134,47],142,[133,133],0,0,"a"]],"old":"","new":"//\n//  AudioConverting.swift\n//  VeilGardeAudio\n//  SPDX-License-Identifier: GPL-3.0-only\n//\n//  WHAT: Door two: a signal resampled to another rate, a clip's speed changed (the resize analog:\n//        its duration scaled by a factor, its pitch by the inverse), and the AAC round trip the\n//        acceptance uses as its re-encode, all through AVFoundation's converter and AVAudioFile.\n//  PIN:  The resampler is AVAudioConverter at its mastering algorithm and highest quality, fed the\n//        whole signal once and flushed; the output is trimmed or zero-padded to round(n · to /\n//        from), so two rates always meet at one length. The AAC round trip writes a transient .m4a\n//        in the temporary directory and deletes it after decoding: the one place this carrier\n//        touches the disk, because AVAudioFile encodes into a container, and the container carries\n//        the encoder's priming, which keeps the decode time-aligned. The lag is still measured\n//        (SignalAlignment) wherever the round trip is used. The bit rate asked for is used when the\n//        encoder offers it at the clip's rate and channel count, else the highest offered below it\n//        (16 kHz mono stops at 48 kb/s, 22.05 kHz mono at 64), and both are reported; the rate\n//        reported is the audio stream's own bytes over the clip's duration, since AVAudioFile pads\n//        the container (measured 2026-11-08: 127,368 audio bytes in a 184,712-byte file).\n//\n\nimport AVFoundation\nimport Foundation\nimport VeilGardeCore\n\npublic enum AudioConverting {\n    /// `mono` at `from` Hz resampled to `to` Hz; identity when the rates agree.\n    public static func resampled(_ mono: [Float], from: Double, to: Double) throws -> [Float] {\n        guard from > 0, to > 0 else { throw VeilGardeFailure.data(\"sample rates must be positive, not \\(from) and \\(to)\") }\n        if from == to || mono.isEmpty { return mono }\n        let expected = Int((Double(mono.count) * to / from).rounded())\n        guard let inFormat = AVAudioFormat(commonFormat: .pcmFormatFloat32, sampleRate: from, channels: 1, interleaved: false),\n              let outFormat = AVAudioFormat(commonFormat: .pcmFormatFloat32, sampleRate: to, channels: 1, interleaved: false),\n              let converter = AVAudioConverter(from: inFormat, to: outFormat) else {\n            throw VeilGardeFailure.internalError(\"no converter from \\(from) Hz to \\(to) Hz\")\n        }\n        converter.sampleRateConverterAlgorithm = AVSampleRateConverterAlgorithm_Mastering\n        converter.sampleRateConverterQuality = AVAudioQuality.max.rawValue\n        guard let input = AVAudioPCMBuffer(pcmFormat: inFormat, frameCapacity: AVAudioFrameCount(mono.count)), let inData = input.floatChannelData else {\n            throw VeilGardeFailure.internalError(\"cannot allocate the resampler's input\")\n        }\n        input.frameLength = AVAudioFrameCount(mono.count)\n        mono.withUnsafeBufferPointer { inData[0].update(from: $0.baseAddress!, count: mono.count) }\n        var out: [Float] = []\n        out.reserveCapacity(expected + 8192)\n        var fed = false\n        var finished = false\n        while !finished {\n            guard let output = AVAudioPCMBuffer(pcmFormat: outFormat, frameCapacity: 65_536), let outData = output.floatChannelData else {\n                throw VeilGardeFailure.internalError(\"cannot allocate the resampler's output\")\n            }\n            var error: NSError?\n            let status = converter.convert(to: output, error: &error) { _, outStatus in\n                if fed {\n                    outStatus.pointee = .endOfStream\n                    return nil\n                }\n                fed = true\n                outStatus.pointee = .haveData\n                return input\n            }\n            if let error { throw VeilGardeFailure.internalError(\"resampling \\(from) Hz to \\(to) Hz failed: \\(error.localizedDescription)\") }\n            out.append(contentsOf: UnsafeBufferPointer(start: outData[0], count: Int(output.frameLength)))\n            switch status {\n            case .haveData: finished = output.frameLength == 0\n            case .inputRanDry, .endOfStream, .error: finished = true\n            @unknown default: finished = true\n            }\n        }\n        if out.count > expected { out.removeLast(out.count - expected) }\n        if out.count < expected { out.append(contentsOf: [Float](repeating: 0, count: expected - out.count)) }\n        return out\n    }\n\n    /// `clip` with its duration scaled by `factor` and its pitch by 1/factor: the samples declared\n    /// at rate / factor and resampled back to the clip's rate, the way a resize scales a picture.\n    public static func speedChanged(_ clip: AudioClip, by factor: Double) throws -> AudioClip {\n        guard factor > 0 else { throw VeilGardeFailure.data(\"a speed factor must be positive, not \\(factor)\") }\n        let channels = try clip.channels.map { try resampled($0, from: clip.sampleRate / factor, to: clip.sampleRate) }\n        return AudioClip(validated: clip.sampleRate, channels: channels)\n    }\n\n    public struct AACRoundTrip: Sendable {\n        /// The decoded clip, at the original rate and channel count.\n        public var clip: AudioClip\n        /// Decoded frames minus the original's.\n        public var lengthDelta: Int\n        /// The rate asked for, and the one the encoder was set to.\n        public var requestedKilobitsPerSecond: Int\n        public var usedKilobitsPerSecond: Int\n        /// The audio stream's bytes over the clip's duration, in kb/s.\n        public var kilobitsPerSecond: Double\n    }\n\n    /// `clip` encoded as AAC at `kilobitsPerSecond` (or the highest offered below it) into a transient .m4a and decoded back.\n    public static func aacRoundTrip(_ clip: AudioClip, kilobitsPerSecond requested: Int) throws -> AACRoundTrip {\n        let url = FileManager.default.temporaryDirectory.appendingPathComponent(\"veilgarde-audio-\\(UUID().uuidString).m4a\")\n        defer { try? FileManager.default.removeItem(at: url) }\n        let offered = aacBitRates(sampleRate: clip.sampleRate, channels: clip.channelCount)\n        let used = offered.isEmpty ? requested : (offered.filter { $0 <= requested }.max() ?? offered.min() ?? requested)\n        let settings: [String: Any] = [\n            AVFormatIDKey: kAudioFormatMPEG4AAC,\n            AVSampleRateKey: clip.sampleRate,\n            AVNumberOfChannelsKey: clip.channelCount,\n            AVEncoderBitRateKey: used * 1000,\n        ]\n        let buffer = try AudioFiles.pcmBuffer(clip)\n        let file: AVAudioFile\n        do {\n            file = try AVAudioFile(forWriting: url, settings: settings, commonFormat: .pcmFormatFloat32, interleaved: false)\n        } catch {\n            throw VeilGardeFailure.data(\"no AAC encoder at \\(used) kb/s for \\(clip.channelCount) channel(s) at \\(clip.sampleRate) Hz: \\(error.localizedDescription)\",\n                                        hint: \"offered: \" + offered.map(String.init).joined(separator: \", \") + \" kb/s\")\n        }\n        do { try file.write(from: buffer) } catch { throw VeilGardeFailure.internalError(\"the AAC encode failed: \\(error.localizedDescription)\") }\n        file.close()\n        let bytes = audioBytes(url) ?? 0\n        let decoded = try AudioFiles.read(url)\n        return AACRoundTrip(clip: decoded, lengthDelta: decoded.frames - clip.frames, requestedKilobitsPerSecond: requested, usedKilobitsPerSecond: used,\n                            kilobitsPerSecond: clip.seconds > 0 ? Double(bytes) * 8 / clip.seconds / 1000 : 0)\n    }\n\n    /// The AAC bit rates the encoder offers for this rate and channel count, in kb/s, ascending.\n    public static func aacBitRates(sampleRate: Double, channels: Int) -> [Int] {\n        var description = AudioStreamBasicDescription(mSampleRate: sampleRate, mFormatID: kAudioFormatMPEG4AAC, mFormatFlags: 0, mBytesPerPacket: 0,\n                                                      mFramesPerPacket: 1024, mBytesPerFrame: 0, mChannelsPerFrame: UInt32(channels), mBitsPerChannel: 0, mReserved: 0)\n        guard let pcm = AVAudioFormat(commonFormat: .pcmFormatFloat32, sampleRate: sampleRate, channels: AVAudioChannelCount(channels), interleaved: false),\n              let aac = AVAudioFormat(streamDescription: &description), let converter = AVAudioConverter(from: pcm, to: aac),\n              let rates = converter.applicableEncodeBitRates else { return [] }\n        return rates.map { $0.intValue / 1000 }.sorted()\n    }\n\n    /// The audio stream's bytes in a file, without its container's padding.\n    static func audioBytes(_ url: URL) -> Int? {\n        var id: AudioFileID?\n        guard AudioFileOpenURL(url as CFURL, .readPermission, 0, &id) == noErr, let id else { return nil }\n        defer { AudioFileClose(id) }\n        var bytes: UInt64 = 0\n        var size = UInt32(MemoryLayout<UInt64>.size)\n        guard AudioFileGetProperty(id, kAudioFilePropertyAudioDataByteCount, &size, &bytes) == noErr else { return nil }\n        return Int(bytes)\n    }\n}\n"},{"path":"Sources/VeilGardeAudio/Audio/AudioFiles.swift","status":"added","lang":"swift","hunks":[[1,0,1,116]],"header":{"lines":[1,13],"target":"VeilGardeAudio","what":[6,8],"pin":[9,12],"in":null,"out":null,"style":"swift"},"marks":[],"first":929,"scopes":[["E","AudioFiles",null,"public",19,19,[19,23],116,null,-1,0,"a",[]],["E","PCMDepth",null,"public",23,23,[23,66],33,null,0,0,"a",["int16","int24","float32"]],["v","bits",null,"public",26,26,[26,29],32,null,1,0,"a"],["S","Info",null,"public",35,35,[35,44],40,null,0,0,"a"],["v","seconds",null,"public",39,39,[39,35],39,null,3,8,"a"],["f","info",["of"],"public static",43,43,[43,56],46,[42,42],0,0,"a"],["f","read",["_"],"public static",49,49,[49,60],71,[48,48],0,0,"a"],["f","open",["_"],"private static",73,73,[73,63],79,null,0,0,"a"],["f","writeWAV",["_","to","depth"],"public static",82,82,[82,97],101,[81,81],0,0,"a"],["f","pcmBuffer",["_"],"static",104,104,[104,72],115,[103,103],0,0,"a"]],"old":"","new":"//\n//  AudioFiles.swift\n//  VeilGardeAudio\n//  SPDX-License-Identifier: GPL-3.0-only\n//\n//  WHAT: Door one: a file to a clip through AVAudioFile, whatever CoreAudio decodes (WAV, AIFF,\n//        CAF, M4A, MP3, FLAC), its rate and length without decoding it, and a clip to a WAV file at\n//        16, 24 or 32 bits.\n//  PIN:  The reader every audio signature is computed through, the twin of the Lens's NSImage rule\n//        (ImageDecoding): decoded as Float32, deinterleaved, at the file's own rate and channel\n//        count, in chunks of 65,536 frames until the file ends. This file and AudioConverting.swift\n//        are the only two that import AVFoundation (PackageLayeringTests holds it).\n//\n\nimport AVFoundation\nimport Foundation\nimport VeilGardeCore\n\npublic enum AudioFiles {\n    /// The file extensions the carrier reads, lowercase.\n    public static let extensions: Set<String> = [\"wav\", \"aif\", \"aiff\", \"aifc\", \"caf\", \"m4a\", \"mp3\", \"aac\", \"flac\", \"mp4\"]\n\n    public enum PCMDepth: String, Codable, Sendable, CaseIterable {\n        case int16, int24, float32\n\n        public var bits: Int {\n            switch self {\n            case .int16: return 16\n            case .int24: return 24\n            case .float32: return 32\n            }\n        }\n    }\n\n    public struct Info: Sendable, Equatable {\n        public var sampleRate: Double\n        public var channels: Int\n        public var frames: Int\n        public var seconds: Double { Double(frames) / sampleRate }\n    }\n\n    /// The file's rate, channel count and length, without decoding it.\n    public static func info(of url: URL) throws -> Info {\n        let file = try open(url)\n        return Info(sampleRate: file.processingFormat.sampleRate, channels: Int(file.processingFormat.channelCount), frames: Int(file.length))\n    }\n\n    /// The whole file as a clip, at its own rate and channel count.\n    public static func read(_ url: URL) throws -> AudioClip {\n        let file = try open(url)\n        let format = file.processingFormat\n        let channelCount = Int(format.channelCount)\n        guard channelCount > 0 else { throw VeilGardeFailure.data(\"\\(url.lastPathComponent) has no audio channel\") }\n        var channels = [[Float]](repeating: [], count: channelCount)\n        let chunk: AVAudioFrameCount = 65_536\n        while true {\n            guard let buffer = AVAudioPCMBuffer(pcmFormat: format, frameCapacity: chunk) else {\n                throw VeilGardeFailure.internalError(\"cannot allocate an audio buffer for \\(url.lastPathComponent)\")\n            }\n            do { try file.read(into: buffer, frameCount: chunk) } catch {\n                throw VeilGardeFailure.data(\"cannot decode \\(url.lastPathComponent): \\(error.localizedDescription)\")\n            }\n            let n = Int(buffer.frameLength)\n            if n == 0 { break }\n            guard let data = buffer.floatChannelData else { throw VeilGardeFailure.internalError(\"\\(url.lastPathComponent) decoded to no float data\") }\n            for c in 0..<channelCount { channels[c].append(contentsOf: UnsafeBufferPointer(start: data[c], count: n)) }\n            if n < Int(chunk) { break }\n        }\n        guard !channels[0].isEmpty else { throw VeilGardeFailure.data(\"\\(url.lastPathComponent) holds no audio\") }\n        return AudioClip(validated: format.sampleRate, channels: channels)\n    }\n\n    private static func open(_ url: URL) throws -> AVAudioFile {\n        do {\n            return try AVAudioFile(forReading: url, commonFormat: .pcmFormatFloat32, interleaved: false)\n        } catch {\n            throw VeilGardeFailure.data(\"cannot read \\(url.lastPathComponent) as audio: \\(error.localizedDescription)\")\n        }\n    }\n\n    /// Writes `clip` as a WAV file at `depth`; the folder must exist.\n    public static func writeWAV(_ clip: AudioClip, to url: URL, depth: PCMDepth = .int16) throws {\n        let settings: [String: Any] = [\n            AVFormatIDKey: kAudioFormatLinearPCM,\n            AVSampleRateKey: clip.sampleRate,\n            AVNumberOfChannelsKey: clip.channelCount,\n            AVLinearPCMBitDepthKey: depth.bits,\n            AVLinearPCMIsFloatKey: depth == .float32,\n            AVLinearPCMIsBigEndianKey: false,\n            AVLinearPCMIsNonInterleaved: false,\n        ]\n        let buffer = try pcmBuffer(clip)\n        let file: AVAudioFile\n        do {\n            file = try AVAudioFile(forWriting: url, settings: settings, commonFormat: .pcmFormatFloat32, interleaved: false)\n        } catch {\n            throw VeilGardeFailure.data(\"cannot write \\(url.lastPathComponent): \\(error.localizedDescription)\")\n        }\n        do { try file.write(from: buffer) } catch { throw VeilGardeFailure.data(\"cannot write \\(url.lastPathComponent): \\(error.localizedDescription)\") }\n        file.close()\n    }\n\n    /// `clip` as a Float32 deinterleaved buffer at its own rate, the shape every writer here takes.\n    static func pcmBuffer(_ clip: AudioClip) throws -> AVAudioPCMBuffer {\n        guard let format = AVAudioFormat(commonFormat: .pcmFormatFloat32, sampleRate: clip.sampleRate, channels: AVAudioChannelCount(clip.channelCount), interleaved: false),\n              let buffer = AVAudioPCMBuffer(pcmFormat: format, frameCapacity: AVAudioFrameCount(max(1, clip.frames))),\n              let data = buffer.floatChannelData else {\n            throw VeilGardeFailure.internalError(\"cannot allocate a \\(clip.channelCount)-channel buffer of \\(clip.frames) frames\")\n        }\n        buffer.frameLength = AVAudioFrameCount(clip.frames)\n        for (c, samples) in clip.channels.enumerated() where !samples.isEmpty {\n            samples.withUnsafeBufferPointer { data[c].update(from: $0.baseAddress!, count: samples.count) }\n        }\n        return buffer\n    }\n}\n"},{"path":"Sources/VeilGardeAudio/Audio/AudioTransforms.swift","status":"added","lang":"swift","hunks":[[1,0,1,56]],"header":{"lines":[1,13],"target":"VeilGardeAudio","what":[6,8],"pin":[9,12],"in":null,"out":null,"style":"swift"},"marks":[],"first":939,"scopes":[["E","AudioTransforms",null,"public",18,18,[18,28],56,null,-1,0,"a",[]],["f","cut",["_","startSample","length"],"public static",20,20,[20,90],24,[19,19],0,0,"a"],["f","gained",["_","dB"],"public static",26,26,[26,74],29,null,0,0,"a"],["f","requantized16Bit",["_"],"public static",32,32,[32,72],36,[31,31],0,0,"a"],["f","withWhiteNoise",["_","snrDB","seed"],"public static",39,39,[39,99],49,[38,38],0,0,"a"],["f","gaussian",["_"],"public static",52,52,[52,67],55,[51,51],0,0,"a"]],"old":"","new":"//\n//  AudioTransforms.swift\n//  VeilGardeAudio\n//  SPDX-License-Identifier: GPL-3.0-only\n//\n//  WHAT: What the acceptance does to a clip before matching it again: a cut (the crop's analog), a\n//        gain change, a requantization to 16 bits, and white noise at a signal-to-noise ratio.\n//        Speed changes and the AAC re-encode live in AudioConverting, behind door two.\n//  PIN:  A cut is clamped to the clip. The requantization rounds each sample to the nearest\n//        1/32767 with no dither, as a 16-bit WAV would store it. The noise is Gaussian by Box–Muller\n//        from SplitMix64, one stream per channel (seed ^ channel + 1), scaled so the mixdown's\n//        RMS over the noise's is the ratio asked for.\n//\n\nimport Foundation\nimport VeilGardeCore\n\npublic enum AudioTransforms {\n    /// `length` samples of `clip` from `startSample`, both clamped to the clip.\n    public static func cut(_ clip: AudioClip, startSample: Int, length: Int) -> AudioClip {\n        let start = max(0, min(startSample, clip.frames))\n        let end = max(start, min(clip.frames, start + max(0, length)))\n        return AudioClip(validated: clip.sampleRate, channels: clip.channels.map { Array($0[start..<end]) })\n    }\n\n    public static func gained(_ clip: AudioClip, dB: Double) -> AudioClip {\n        let gain = Float(pow(10, dB / 20))\n        return AudioClip(validated: clip.sampleRate, channels: clip.channels.map { $0.map { $0 * gain } })\n    }\n\n    /// Every sample on the 16-bit grid, clamped to full scale.\n    public static func requantized16Bit(_ clip: AudioClip) -> AudioClip {\n        AudioClip(validated: clip.sampleRate, channels: clip.channels.map { channel in\n            channel.map { x in Float(max(-32768, min(32767, (Double(x) * 32767).rounded())) / 32767) }\n        })\n    }\n\n    /// `clip` plus white Gaussian noise at `snrDB` below the mixdown's RMS.\n    public static func withWhiteNoise(_ clip: AudioClip, snrDB: Double, seed: UInt64) -> AudioClip {\n        let level = clip.rmsDBFS\n        guard level.isFinite else { return clip }\n        let noiseRMS = pow(10, (level - snrDB) / 20)\n        var channels: [[Float]] = []\n        for (c, channel) in clip.channels.enumerated() {\n            var rng = SplitMix64(seed: seed ^ UInt64(c + 1))\n            channels.append(channel.map { Float(Double($0) + noiseRMS * gaussian(&rng)) })\n        }\n        return AudioClip(validated: clip.sampleRate, channels: channels)\n    }\n\n    /// A standard normal draw by Box–Muller.\n    public static func gaussian(_ rng: inout SplitMix64) -> Double {\n        let u1 = max(rng.unit(), 1e-300), u2 = rng.unit()\n        return (-2 * log(u1)).squareRoot() * cos(2 * Double.pi * u2)\n    }\n}\n"},{"path":"Sources/VeilGardeAudio/README.md","status":"added","lang":"markdown","hunks":[[1,0,1,109]],"header":null,"marks":[],"first":945,"scopes":[],"old":"","new":"# VeilGardeAudio: the watermark on sound\n\nThis target carries VeilGarde's watermark to audio. A clip is drawn as its spectrogram, and `Watermark.sign` signs that picture unchanged. Nothing is written into the sound. The picture goes back to sound through the exact inverse transform.\n\nThese notes direct the research. **For now the research is speech protection only.** Music results are held as observations and are not being pursued.\n\nStatus on 2026-11-08, when the work was closed for the day:\n\n| Question | Answer today |\n|---|---|\n| Does v1 on sound pass its acceptance on speech, with today's matcher? | No. Killed: 30.8% of cuts found with their offset, under the 60% bar |\n| Does it pass when the matcher reads the grid at every frame? | Yes, as an experiment: every cut found at its exact column, 85% recall at 0.86 with no false match |\n| …and with quarter-hop offsets of the cut too? | Yes, as an experiment on 20 clips: median cut score 0.974, 90% recall at 0.95 with no false match |\n| Has the shipped default changed? | No. The matcher reads four phases until the owner picks a proposal |\n| Do the macOS voices leave a synthesis step the residual can see? | No. 0 of 56 utterances at 8 ms resolution; only prosody |\n| Does a recorded human voice differ from a generated one? | Not measured. There is no recorded speech yet |\n\n## What exists\n\n- **The speech profile.** 16 kHz mono, 1024-sample frames every 256, a picture 512 rows tall, 16 tile rows. One tile is 512 ms by 500 Hz. A half cut of a 9 s utterance holds 320 to 564 bits.\n- **The picture.** Each bin's magnitude as one of 256 grey levels on a fixed scale from −96 to 0 dBFS, the highest bin in the top row, in the 8-bit bitmap the lens already reads. The exact inverse returns the sound at 129 to 130 dB SNR; from the 8-bit picture alone, a median of 43 dB on speech.\n- **The acceptance** (`veilgarde audio accept`), mirrored from the image watermark's with the same kill criterion: a half-length cut at a random sample, an AAC re-encode, a cross match against the next clip. `--phases 0,1,…,31` reads the grid at every frame. `--sub-hop 4` also tries the cut at quarter-hop offsets and keeps the best.\n- **The time-phase study** (`veilgarde audio phases`). The fragility read at every time phase as a trace dense in time, the residual's slope per picture column beside it, sections of 0.5 to 2 s compared with the whole clip, and the traces' spectra read for time steps. Rules are fixed before a run in a `rules.md`, and `judge.py` reads every hypothesis row off the reports.\n- **The corpus.** `Scripts/audio-corpus.sh` renders 56 utterances: seven macOS voices reading eight fixed sentences. One fixture, `say_samantha_12s.wav`, is pinned in the tests.\n\n## Phase 1: the carrier\n\nv1 on speech was killed by its acceptance, 39 utterances, seed 0:\n\n| Measure | Result | Bar |\n|---|---|---|\n| Self-match | 100% | 100% |\n| A half cut matched with its offset | 30.8% | at least 60% |\n| AAC at 64 kb/s, median score | 0.907 | at least 0.75 |\n| Best recall at any threshold | 69.2% | 80% at most 5% false |\n| False matches at 0.75 | 0% | at most 5% |\n\nWhat held: every cut that started on a tile boundary matched, 39 of 39. Gain of −6 dB and 16-bit requantization matched on every utterance. What failed: cuts landed between the matcher's four grid phases, every 8 frames apart; cuts 1 to 4 frames off matched 1 of 23. White noise at 30 dB broke the signature on 33 of 39 utterances. Speed changes matched none.\n\n## Phase 2: the time phases\n\n**The study.** On all 56 utterances at quarter hop, a column every 4 ms: no time step between 8 and 20 ms, 0 of 56; one unconfirmed line at 8 ms; every line above the bar was prosodic, 211 to 1986 ms. The AAC frame left no step in 16 re-encodes. No utterance had a recurring section. These voices leave no synthesis step the residual can see at this resolution.\n\n**The matcher.** The first fallback named before phase 1, a finer time-phase search, was measured with the kill criterion unchanged:\n\n| Search | Clips | Cut found with its offset | Cut score, median | False at 0.75 | Operating point |\n|---|---|---|---|---|---|\n| 4 phases, today's default | 39 | 30.8% | 0.712 | 0% | 80% recall not reached |\n| A: 32 phases | 39 | 100% | 0.911 | 2 of 39 | 0.86: recall 85%, false 0% |\n| B: 32 phases × quarter hops | 20 | 100% | 0.974 | 2 of 20 | 0.95: recall 90%, false 0% |\n\nThe prediction written before A held. B's median cut score rose 0.063 over A, past the 0.05 rule set beforehand, so the sub-hop shift matters. Cost per clip: 2 s today, 5 s for A, 18 s for B.\n\n**The controls.** A click train every quarter second is found under the music profile, 5 of 5. Under the speech profile its line stands at z 19 to 22 in every clip, but the rule wants both the second and third harmonic, and it confirms 1 of 5. Noise and silence show nothing.\n\n## What the numbers do not cover\n\nRead the passes narrowly:\n\n- **One synthetic corpus.** Seven classic macOS voices, clean, no room, no microphone. No recorded human speech, and no neural voice.\n- **Few clips.** 39 and 20. With 20 strangers, a false-match rate of 2 in 20 at 0.75 could be anywhere from about 1% to 30%.\n- **Few bits.** A half cut carries a few hundred bits; a stranger's median score is 0.71.\n- **Clean cuts.** The cuts come from the same decoded samples. Noise, rooms, phone codecs and re-recording were not part of the passing runs, and in phase 1 noise at 30 dB broke 33 of 39.\n\n## Where speech protection goes next\n\nIn order, each with its rule written before it runs:\n\n1. **Choose the proposal.** A is cheap and passes; B is sharper and slower. The owner decides; the default does not move until then (ledger decision-150).\n2. **Record real speech.** A `veilgarde audio record` command, raw PCM from the default input, through one of the two AVFoundation doors, and a corpus of recorded voices reading the same sentences (ledger question-33). This is what the generated-against-recorded question needs.\n3. **A bigger, harder corpus.** Hundreds of clips from many speakers, so false matches are measured on more than 40 strangers.\n4. **Speech's real transforms.** Noise at 10 to 30 dB, room reverberation, a speaker-to-microphone re-recording, telephone bandwidth and codecs (8 kHz narrowband, Opus, AMR), speed and pitch. Noise is the first: it broke phase 1.\n5. **More bits per second.** Speech pictures hold 16 tile rows; a short clip is thin. A profile with more rows, or a matcher that pools several cuts, is a proposal to measure, not a change.\n6. **The theory.** A neural voice beside the classic ones and beside recorded speech, through `audio phases` at quarter or eighth hop.\n7. **Instrument fixes**, for the study's third pass: confirm a line by any two of its first three harmonics, so the click train under speech passes; widen the harmonic tolerance with the line's width.\n\n## Returning to it\n\n```sh\n# the carrier's tests, with the GPU; the pins hold the three clips exactly\nVEILGARDE_MLX_TESTS=1 Scripts/test.sh --filter VeilGardeAudioTests\n\nW=$VEILGARDE_WORK_AREA\nexport VEILGARDE_CONFIG=release\n# the speech corpus, if the work area lacks it\nScripts/audio-corpus.sh --out $W/audio/corpus\n# experiment A and B, the kill criterion unchanged\nScripts/cli.sh audio accept --audio $W/audio/corpus/speech --profile speech --segment 0 --n 40 --seed 0 --phases $(seq -s, 0 31) --out $W/audio/accept_speech_phases32_n40.json\nScripts/cli.sh audio accept --audio $W/audio/corpus/speech --profile speech --segment 0 --n 20 --seed 0 --phases $(seq -s, 0 31) --sub-hop 4 --out $W/audio/accept_speech_phases32_subhop4_n20.json\n# the time-phase study on speech, and its judge\nScripts/cli.sh audio phases --audio $W/audio/corpus/speech --profile speech --sub-hop 4 --out $W/research/audio-phases-<date>/s\npython3 -I $W/research/audio-phases-20261108/judge.py $W/research/audio-phases-<date>\n```\n\nThe 2026-11-08 record: the reports under `<work area>/audio/` and `<work area>/research/audio-phases-20261108/` (`rules.md`, `summary.md`, `judge.py`), the site's chapter 11 and trails AR, AM and AT, and the ledger's amendments 29 to 32, decisions 137 to 151 and commands 123 to 143. One MLX workload at a time: check `ioreg -r -c AGXDeviceUserClient -l` before a long run.\n\n## Music, held\n\nUnder the music profile phase 1 was killed by false matches between neighbouring seconds of one track. The time-phase study found the beat as the dominant step in every segment of three masters, and no step under 20 ms. The finer search was not run on music. None of this is pursued while speech is the focus.\n\n## Where the code lives\n\n| Folder | Holds |\n|---|---|\n| `Audio/` | the clip; the two doors, `AudioFiles.swift` and `AudioConverting.swift`, the only files that import AVFoundation; the transforms |\n| `Spectrogram/` | the two profiles, the analysis signal, the framing, the transform and its inverse, the grey mapping, the picture, the lag finder |\n| `Watermark/` | sign and match through the image watermark, the time phases, the round trips |\n| `Acceptance/` | synthetic clips, the corpus sample, the acceptance and its kill criterion |\n| `Research/` | the time-phase study: the trace, the section recurrence, the periodicity scan, the study's rows and reports |\n"},{"path":"Sources/VeilGardeAudio/Research/FragilityTrace.swift","status":"added","lang":"swift","hunks":[[1,0,1,145]],"header":{"lines":[1,18],"target":"VeilGardeAudio","what":[6,10],"pin":[11,17],"in":null,"out":null,"style":"swift"},"marks":[],"first":945,"scopes":[["S","FragilityTrace",null,"public",27,27,[27,50],145,null,-1,0,"a"],["v","columnSeconds",null,"public",44,44,[44,37],44,[43,43],0,8,"a"],["v","columnSamples",null,"public",45,45,[45,37],45,null,0,8,"a"],["f","fr",["row","column"],"public",47,47,[47,51],47,null,0,8,"a"],["f","residual",["row","column"],"public",48,48,[48,57],48,null,0,8,"a"],["f","frRow",["_"],"public",49,49,[49,45],49,null,0,8,"a"],["f","residualRow",["_"],"public",50,50,[50,51],50,null,0,8,"a"],["v","frameResolution",null,"public",53,53,[53,47],62,[52,52],0,0,"a"],["f","measure",["_"],"public static",65,65,[65,83],107,[64,64],0,0,"a"],["f","measure",["_","profile","subHop"],"public static",110,110,[110,121],114,[109,109],0,0,"a"],["f","measure",["_","subHop"],"public static",116,116,[116,99],126,null,0,0,"a"],["f","interleave",["_"],"static",129,129,[129,73],144,[128,128],0,0,"a"]],"old":"","new":"//\n//  FragilityTrace.swift\n//  VeilGardeAudio\n//  SPDX-License-Identifier: GPL-3.0-only\n//\n//  WHAT: A clip's fragility dense in time, the time-phase study's instrument: T, the fragility\n//        rate of the tile anchored at every frame (the watermark's grid read at all 32 time phases\n//        and interleaved), and E, the residual's slope per picture column averaged over the 32\n//        tiles that cover it, finer than a tile. At quarter or eighth hops the signal is shifted\n//        by a fraction of a hop and the traces interleaved, so the time axis is that much finer.\n//  PIN:  T[r, f] is the grid read at phase f mod 32, column f / 32, so T[r, 32c] equals the\n//        signature's own grid value (TraceTests). E is the mean over bins of (high − low) / 0.025\n//        per tile column, averaged over the tiles covering a picture column; the mean of a tile's\n//        32 columns is its fragility rate, so T is E box-filtered over 32 frames. The warps, the\n//        strengths, the tile cut and the eval budget are the watermark's own, called through their\n//        public surface; nothing is changed or bypassed. Research code: nothing here is read by\n//        signing or matching.\n//\n\nimport CoreGraphics\nimport Foundation\nimport MLX\nimport VeilGardeCore\nimport VeilGardeLens\nimport VeilWatermark\n\npublic struct FragilityTrace: Sendable, Equatable {\n    public let profile: SpectrogramProfile\n    /// Columns per frame: 1, 4 or 8.\n    public let subHop: Int\n    public let rows: Int\n    /// The picture's frames, per sub-hop step.\n    public let frames: Int\n    /// T's columns: (frames − 31) · subHop.\n    public let columns: Int\n    /// E's columns: frames · subHop.\n    public let pictureColumns: Int\n    /// T, row-major rows × columns.\n    public let fr: [Float]\n    /// E, row-major rows × pictureColumns.\n    public let residual: [Float]\n\n    /// The time one column stands for.\n    public var columnSeconds: Double { Double(profile.hop) / Double(subHop) / profile.sampleRate }\n    public var columnSamples: Double { Double(profile.hop) / Double(subHop) }\n\n    public func fr(row: Int, column: Int) -> Float { fr[row * columns + column] }\n    public func residual(row: Int, column: Int) -> Float { residual[row * pictureColumns + column] }\n    public func frRow(_ row: Int) -> [Float] { Array(fr[(row * columns)..<((row + 1) * columns)]) }\n    public func residualRow(_ row: Int) -> [Float] { Array(residual[(row * pictureColumns)..<((row + 1) * pictureColumns)]) }\n\n    /// T at frame resolution: every subHop-th column, phase 0.\n    public var frameResolution: FragilityTrace {\n        guard subHop > 1 else { return self }\n        let tc = columns / subHop, pc = pictureColumns / subHop\n        var f = [Float](repeating: 0, count: rows * tc), e = [Float](repeating: 0, count: rows * pc)\n        for r in 0..<rows {\n            for c in 0..<tc { f[r * tc + c] = fr[r * columns + c * subHop] }\n            for c in 0..<pc { e[r * pc + c] = residual[r * pictureColumns + c * subHop] }\n        }\n        return FragilityTrace(profile: profile, subHop: 1, rows: rows, frames: frames, columns: tc, pictureColumns: pc, fr: f, residual: e)\n    }\n\n    /// The trace of one picture at frame resolution: 32 grid reads, interleaved.\n    public static func measure(_ image: SpectrogramImage) throws -> FragilityTrace {\n        defer { LensRuntime.releaseMemory() }\n        let ts = WarpConstants.tileSize\n        let plane = try NativePlane(try image.cgImage)\n        let rows = plane.height / ts, width = plane.width\n        guard width >= ts, rows > 0 else { throw VeilGardeFailure.data(\"a picture of \\(width) frames and \\(plane.height) rows holds no full tile\") }\n        let traceColumns = width - ts + 1\n        var fr = [Float](repeating: 0, count: rows * traceColumns)\n        var sum = [Double](repeating: 0, count: rows * width)\n        var count = [Int](repeating: 0, count: rows * width)\n        let tables = WarpTables.shared(quantizeLikeCV2: true)\n        let strength = WarpConstants.highStrength - WarpConstants.lowStrength\n        for phase in 0..<ts {\n            let cols = (width - phase) / ts\n            guard cols > 0 else { continue }\n            let region = plane.array[0..<(rows * ts), phase..<(phase + cols * ts), 0...]\n            let tiles = region.reshaped([rows, ts, cols, ts, 3]).transposed(0, 2, 1, 3, 4).reshaped([rows * cols, ts * ts, 3])\n            var a = 0\n            while a < rows * cols {\n                let b = min(a + WarpConstants.evalTileBudget, rows * cols)\n                let chunk = tiles[a..<b]\n                let low = WarpResidual.batch(chunk, forward: tables.lowForward, back: tables.lowBack)\n                let high = WarpResidual.batch(chunk, forward: tables.highForward, back: tables.highBack)\n                let rate = WarpResidual.fragility(low: low, high: high)\n                let perColumn = ((high - low) / strength).mean(axes: [1])\n                MLX.eval(rate, perColumn)\n                let rates = rate.asArray(Float.self), columnValues = perColumn.asArray(Float.self)\n                for k in a..<b {\n                    let r = k / cols, c = k % cols\n                    let f = phase + c * ts\n                    fr[r * traceColumns + f] = rates[k - a]\n                    for tx in 0..<ts {\n                        sum[r * width + f + tx] += Double(columnValues[(k - a) * ts + tx])\n                        count[r * width + f + tx] += 1\n                    }\n                }\n                a = b\n            }\n        }\n        var residual = [Float](repeating: 0, count: rows * width)\n        for i in residual.indices where count[i] > 0 { residual[i] = Float(sum[i] / Double(count[i])) }\n        return FragilityTrace(profile: image.profile, subHop: 1, rows: rows, frames: width, columns: traceColumns, pictureColumns: width, fr: fr, residual: residual)\n    }\n\n    /// The trace of a clip under `profile`, at frame resolution or at quarter or eighth hops.\n    public static func measure(_ clip: AudioClip, profile: SpectrogramProfile, subHop: Int = 1) throws -> FragilityTrace {\n        guard [1, 4, 8].contains(subHop) else { throw VeilGardeFailure.usage(\"--sub-hop must be 1, 4 or 8, not \\(subHop)\") }\n        let signal = try AnalysisSignal(clip, profile: profile)\n        return try measure(signal, subHop: subHop)\n    }\n\n    public static func measure(_ signal: AnalysisSignal, subHop: Int = 1) throws -> FragilityTrace {\n        guard [1, 4, 8].contains(subHop) else { throw VeilGardeFailure.usage(\"--sub-hop must be 1, 4 or 8, not \\(subHop)\") }\n        if subHop == 1 { return try measure(SpectrogramImage(Spectrogram(signal))) }\n        var traces: [FragilityTrace] = []\n        for q in 0..<subHop {\n            let delta = q * signal.profile.hop / subHop\n            let shifted = AnalysisSignal(profile: signal.profile, samples: Array(signal.samples.dropFirst(delta)))\n            traces.append(try measure(SpectrogramImage(Spectrogram(shifted))))\n        }\n        return interleave(traces)\n    }\n\n    /// Traces of the same clip at successive sub-hop shifts, column q of every frame.\n    static func interleave(_ traces: [FragilityTrace]) -> FragilityTrace {\n        let subHop = traces.count\n        let frames = traces.map(\\.frames).min() ?? 0\n        let rows = traces[0].rows, ts = WarpConstants.tileSize\n        let tc = max(0, frames - ts + 1)\n        var fr = [Float](repeating: 0, count: rows * tc * subHop)\n        var residual = [Float](repeating: 0, count: rows * frames * subHop)\n        for (q, t) in traces.enumerated() {\n            for r in 0..<rows {\n                for f in 0..<tc { fr[(r * tc + f) * subHop + q] = t.fr[r * t.columns + f] }\n                for x in 0..<frames { residual[(r * frames + x) * subHop + q] = t.residual[r * t.pictureColumns + x] }\n            }\n        }\n        return FragilityTrace(profile: traces[0].profile, subHop: subHop, rows: rows, frames: frames, columns: tc * subHop, pictureColumns: frames * subHop,\n                              fr: fr, residual: residual)\n    }\n}\n"},{"path":"Sources/VeilGardeAudio/Research/PeriodicityScan.swift","status":"added","lang":"swift","hunks":[[1,0,1,221]],"header":{"lines":[1,27],"target":"VeilGardeAudio","what":[6,10],"pin":[11,26],"in":null,"out":null,"style":"swift"},"marks":[],"first":957,"scopes":[["S","PeriodicityPeak",null,"public",33,33,[33,60],44,null,-1,0,"a"],["S","PeriodicityProbe",null,"public",46,46,[46,61],49,null,-1,0,"a"],["S","Periodicity",null,"public",51,51,[51,56],68,null,-1,0,"a"],["E","PeriodicityScan",null,"public",70,70,[70,28],221,null,-1,0,"a",[]],["f","scan",["_","lagMin","columnSeconds","columnSamples","probes","longestLagSeconds","smoothingSeconds"],"public static",79,79,[80,135],181,[78,78],3,0,"a"],["f","empty",["flat","used"],"",85,85,[85,57],88,null,4,4,"a"],["f","z",["_"],"",121,121,[121,35],121,null,4,12,"a"],["f","isLocalMaximum",["_"],"",122,122,[122,46],125,null,4,4,"a"],["f","period",["_"],"",126,126,[126,40],126,null,4,12,"a"],["f","peak",["_","confirmed","fundamental"],"",127,127,[127,83],131,null,4,4,"a"],["f","tolerance",["_"],"",132,132,[132,43],132,null,4,12,"a"],["f","line",["near","atLeast"],"",134,134,[134,59],141,[133,133],4,4,"a"],["f","isHarmonic",["_"],"",151,151,[151,42],157,[150,150],4,4,"a"],["f","prepared",["_","window"],"static",184,184,[184,67],207,[183,183],3,0,"a"],["f","median",["_"],"static",209,209,[209,53],213,null,3,0,"a"],["f","robust",["_"],"static",216,216,[216,76],220,[215,215],3,0,"a"]],"old":"","new":"//\n//  PeriodicityScan.swift\n//  VeilGardeAudio\n//  SPDX-License-Identifier: GPL-3.0-only\n//\n//  WHAT: The recurring time steps in a trace: each row standardized and freed of its slow drift,\n//        windowed and transformed, the rows' power spectra pooled, and the spectral lines that\n//        stand above a running baseline, confirmed by their harmonics. A confirmed line with no\n//        confirmed line at half or a third of its frequency is a fundamental: a time step. The\n//        dominant step is the strongest fundamental.\n//  PIN:  Rules fixed before any run (ledger decision-148, amended before the first run when the\n//        planted-sinusoid test showed a robust z on the autocorrelation cannot see a clean period,\n//        since the autocorrelation of a periodic series is itself periodic and its spread swamps\n//        the peak). A centred moving average of 4 s is subtracted, a periodic Hann applied, the\n//        series zero-padded to four times its length and transformed on Frigate's FFT; the power\n//        is pooled as the mean over rows with spread, and rows of zero spread, under one part in\n//        ten thousand of their level, are skipped; a trace with none left is flat. Only periods between the shortest and longest lag are read. The\n//        power is read in the log, where its noise is near symmetric; the baseline is the running\n//        median over ±2.5% of the band, eight bins at least; z = (log power − baseline) / the\n//        larger of 1.4826·MAD of that residual over the band and 1/√rows, the log power's own\n//        noise when the rows average (a band smooth enough for the running median to reproduce it\n//        would otherwise read a zero spread). A line is a local maximum with z ≥ 4; it is confirmed when its second\n//        harmonic, and its third where it fits in the band, are local maxima with z ≥ 2 within 1%\n//        of their bin, two bins at least. A confirmed line within that tolerance of an integer\n//        multiple of a lower confirmed line's bin is a harmonic, not a fundamental. A period is read\n//        as nfft / bin, in columns.\n//\n\nimport Foundation\nimport MLX\nimport VeilGardeLens\n\npublic struct PeriodicityPeak: Codable, Sendable, Equatable {\n    /// The period in columns, nfft / bin, and its rounding.\n    public var period: Double\n    public var lag: Int\n    public var samples: Double\n    public var milliseconds: Double\n    public var power: Double\n    public var z: Double\n    public var confirmed: Bool\n    /// Confirmed, and not itself the harmonic of a confirmed line: a time step.\n    public var fundamental: Bool\n}\n\npublic struct PeriodicityProbe: Codable, Sendable, Equatable {\n    public var lag: Double\n    public var z: Double\n}\n\npublic struct Periodicity: Codable, Sendable, Equatable {\n    public var lagMin: Int\n    public var lagMax: Int\n    public var columnSeconds: Double\n    public var nfft: Int\n    public var rowsUsed: Int\n    public var flat: Bool\n    /// Every line with z ≥ 2, so the harmonics a reader confirms a line by are on record.\n    public var peaks: [PeriodicityPeak]\n    /// The confirmed fundamentals, shortest first.\n    public var steps: [PeriodicityPeak]\n    /// The strongest fundamental.\n    public var dominant: PeriodicityPeak?\n    /// z at the lags asked for.\n    public var probes: [PeriodicityProbe]\n    /// z over the band at 512 points from the longest period to the shortest, for the figure.\n    public var curve: [Double]\n}\n\npublic enum PeriodicityScan {\n    public static let peakZ = 4.0\n    public static let harmonicZ = 2.0\n    public static let longestLagSeconds = 2.0\n    public static let smoothingSeconds = 4.0\n    public static let padding = 4\n    public static let curvePoints = 512\n\n    /// `series` is one array per row of equal length; `columnSeconds` and `columnSamples` convert a lag; `probes` are lags whose z is wanted.\n    public static func scan(_ series: [[Float]], lagMin: Int, columnSeconds: Double, columnSamples: Double, probes: [Double] = [],\n                            longestLagSeconds: Double = longestLagSeconds, smoothingSeconds: Double = smoothingSeconds) -> Periodicity {\n        let length = series.first?.count ?? 0\n        let lagMax = min(length / 2, Int(longestLagSeconds / columnSeconds))\n        var nfft = 1\n        while nfft < length * padding { nfft <<= 1 }\n        func empty(flat: Bool, used: Int) -> Periodicity {\n            Periodicity(lagMin: lagMin, lagMax: lagMax, columnSeconds: columnSeconds, nfft: nfft, rowsUsed: used, flat: flat, peaks: [], steps: [], dominant: nil,\n                        probes: probes.map { PeriodicityProbe(lag: $0, z: 0) }, curve: [])\n        }\n        guard lagMax > lagMin, length > 2 * lagMin else { return empty(flat: false, used: 0) }\n        let window = max(3, Int(smoothingSeconds / columnSeconds) | 1)\n        let hann = (0..<length).map { 0.5 - 0.5 * cos(2 * Double.pi * Double($0) / Double(length)) }\n        var rows: [Float] = []\n        var used = 0\n        for row in series {\n            guard let detrended = prepared(row, window: window) else { continue }\n            used += 1\n            var padded = [Float](repeating: 0, count: nfft)\n            for i in 0..<length { padded[i] = Float(detrended[i] * hann[i]) }\n            rows.append(contentsOf: padded)\n        }\n        guard used > 0 else { return empty(flat: true, used: 0) }\n        let power: [Double] = {\n            defer { LensRuntime.releaseMemory() }\n            let x = MLXFFT.rfft(MLXArray(rows, [used, nfft]), axis: 1)\n            let re = x.realPart(), im = x.imaginaryPart()\n            let p = (re * re + im * im).mean(axes: [0])\n            MLX.eval(p)\n            return p.asArray(Float.self).map(Double.init)\n        }()\n        // The band: bins whose period nfft / b lies between lagMin and lagMax.\n        let bLo = max(1, Int((Double(nfft) / Double(lagMax)).rounded(.up))), bHi = min(power.count - 1, Int(Double(nfft) / Double(lagMin)))\n        guard bHi > bLo + 8 else { return empty(flat: false, used: used) }\n        let band = Array(power[bLo...bHi])\n        let logBand = band.map { log(max($0, 1e-30)) }\n        let half = max(8, band.count / 80)\n        var baseline = [Double](repeating: 0, count: band.count)\n        for i in band.indices { baseline[i] = median(Array(logBand[max(0, i - half)...min(band.count - 1, i + half)])) }\n        let residual = zip(logBand, baseline).map { $0 - $1 }\n        let (_, mad) = robust(residual)\n        let scale = max(1.4826 * mad, 1 / Double(used).squareRoot())\n        func z(_ i: Int) -> Double { residual[i] / scale }\n        func isLocalMaximum(_ i: Int) -> Bool {\n            let left = i > 0 ? band[i - 1] : -.infinity, right = i + 1 < band.count ? band[i + 1] : -.infinity\n            return band[i] > left && band[i] >= right\n        }\n        func period(_ i: Int) -> Double { Double(nfft) / Double(i + bLo) }\n        func peak(_ i: Int, confirmed: Bool, fundamental: Bool) -> PeriodicityPeak {\n            let p = period(i)\n            return PeriodicityPeak(period: p, lag: Int(p.rounded()), samples: p * columnSamples, milliseconds: p * columnSeconds * 1000, power: band[i], z: z(i),\n                                   confirmed: confirmed, fundamental: fundamental)\n        }\n        func tolerance(_ b: Double) -> Int { max(2, Int((0.01 * b).rounded())) }\n        /// A local maximum with z ≥ `atLeast` within the tolerance of bin `b`.\n        func line(near b: Double, atLeast: Double) -> Bool {\n            let tolerance = tolerance(b)\n            for candidate in (Int(b.rounded()) - tolerance)...(Int(b.rounded()) + tolerance) {\n                let i = candidate - bLo\n                if i >= 0, i < band.count, isLocalMaximum(i), z(i) >= atLeast { return true }\n            }\n            return false\n        }\n        var candidates: [(i: Int, confirmed: Bool)] = []\n        for i in band.indices where isLocalMaximum(i) && z(i) >= harmonicZ {\n            let b = Double(i + bLo)\n            var confirmed = z(i) >= peakZ && 2 * b <= Double(bHi) && line(near: 2 * b, atLeast: harmonicZ)\n            if confirmed && 3 * b <= Double(bHi) { confirmed = line(near: 3 * b, atLeast: harmonicZ) }\n            candidates.append((i, confirmed))\n        }\n        let confirmedBins = candidates.filter(\\.confirmed).map { $0.i + bLo }.sorted()\n        /// A confirmed line at a lower bin of which `b` is an integer multiple, within the tolerance.\n        func isHarmonic(_ b: Int) -> Bool {\n            for lower in confirmedBins where Double(b) / Double(lower) >= 1.9 {\n                let m = (Double(b) / Double(lower)).rounded()\n                if abs(Double(b) - m * Double(lower)) <= Double(tolerance(Double(b))) { return true }\n            }\n            return false\n        }\n        var peaks: [PeriodicityPeak] = []\n        for (i, confirmed) in candidates {\n            peaks.append(peak(i, confirmed: confirmed, fundamental: confirmed && !isHarmonic(i + bLo)))\n        }\n        let steps = peaks.filter(\\.fundamental).sorted { $0.period < $1.period }\n        var curve = [Double](repeating: 0, count: curvePoints)\n        for k in 0..<curvePoints {\n            let i = min(band.count - 1, Int(Double(k) * Double(band.count - 1) / Double(curvePoints - 1)))\n            curve[k] = z(i)\n        }\n        let probed = probes.map { lag -> PeriodicityProbe in\n            guard lag > 0 else { return PeriodicityProbe(lag: lag, z: 0) }\n            let b = Double(nfft) / lag\n            let tolerance = tolerance(b)\n            var best = -Double.infinity\n            for candidate in (Int(b.rounded()) - tolerance)...(Int(b.rounded()) + tolerance) {\n                let i = candidate - bLo\n                if i >= 0, i < band.count { best = max(best, z(i)) }\n            }\n            return PeriodicityProbe(lag: lag, z: best.isFinite ? best : 0)\n        }\n        return Periodicity(lagMin: lagMin, lagMax: lagMax, columnSeconds: columnSeconds, nfft: nfft, rowsUsed: used, flat: false, peaks: peaks, steps: steps,\n                           dominant: steps.max { $0.z < $1.z }, probes: probed, curve: curve)\n    }\n\n    /// A row standardized and freed of its centred moving average; nil when it has no spread.\n    static func prepared(_ row: [Float], window: Int) -> [Double]? {\n        let n = row.count\n        guard n > 1 else { return nil }\n        var mean = 0.0\n        for x in row { mean += Double(x) }\n        mean /= Double(n)\n        var variance = 0.0\n        for x in row { variance += (Double(x) - mean) * (Double(x) - mean) }\n        variance /= Double(n)\n        let sd = variance.squareRoot()\n        // A row whose spread is under one part in ten thousand of its level is flat: a stationary tone's picture is constant along\n        // time, and what remains is the arithmetic's own ripple, which the first run read as steps of 53 and 87 ms (N1, 2026-11-08).\n        guard sd > 1e-4 * max(abs(mean), 1e-30) else { return nil }\n        let x = row.map { (Double($0) - mean) / sd }\n        var prefix = [Double](repeating: 0, count: n + 1)\n        for i in 0..<n { prefix[i + 1] = prefix[i] + x[i] }\n        let half = window / 2\n        var out = [Double](repeating: 0, count: n)\n        for i in 0..<n {\n            let lo = max(0, i - half), hi = min(n - 1, i + half)\n            out[i] = x[i] - (prefix[hi + 1] - prefix[lo]) / Double(hi - lo + 1)\n        }\n        return out\n    }\n\n    static func median(_ values: [Double]) -> Double {\n        guard !values.isEmpty else { return 0 }\n        let s = values.sorted()\n        return s.count % 2 == 1 ? s[s.count / 2] : (s[s.count / 2 - 1] + s[s.count / 2]) / 2\n    }\n\n    /// The median and the median absolute deviation.\n    static func robust(_ values: [Double]) -> (median: Double, mad: Double) {\n        guard !values.isEmpty else { return (0, 0) }\n        let m = median(values)\n        return (m, median(values.map { abs($0 - m) }))\n    }\n}\n"},{"path":"Sources/VeilGardeAudio/Research/SectionRecurrence.swift","status":"added","lang":"swift","hunks":[[1,0,1,158]],"header":{"lines":[1,17],"target":"VeilGardeAudio","what":[6,8],"pin":[9,16],"in":null,"out":null,"style":"swift"},"marks":[],"first":973,"scopes":[["S","SectionPeak",null,"public",22,22,[22,56],28,null,-1,0,"a"],["S","SectionRecurrenceFound",null,"public",30,30,[30,67],35,null,-1,0,"a"],["S","SectionReport",null,"public",37,37,[37,58],45,null,-1,0,"a"],["S","SectionSet",null,"public",47,47,[47,55],52,null,-1,0,"a"],["E","SectionRecurrence",null,"public",54,54,[54,30],158,null,-1,0,"a",[]],["f","scan",["_","sectionSeconds"],"public static",58,58,[58,112],71,null,4,0,"a"],["f","denseCodes",["_"],"static",74,74,[74,83],89,[73,73],4,0,"a"],["f","section",["_","codes","start","length"],"static",91,91,[91,131],138,null,4,0,"a"],["f","recurrence",["start","peaks","columnSeconds"],"static",141,141,[141,105],157,[140,140],4,0,"a"]],"old":"","new":"//\n//  SectionRecurrence.swift\n//  VeilGardeAudio\n//  SPDX-License-Identifier: GPL-3.0-only\n//\n//  WHAT: The owner's slicing: a clip's trace cut into sections of a fixed length, each section's\n//        block compared with the whole trace at every offset, the offsets that agree, and the\n//        recurrences among them, a step and a phase.\n//  PIN:  Rules fixed before any run (ledger decision-148): sections start at 0, ℓ, 2ℓ, … on T at\n//        frame resolution; S(o) is the Pearson correlation of the two blocks over rows × ℓ, the\n//        matcher's bit agreement on codes derived from T beside it; offsets within ℓ + 32 of the\n//        section are excluded, since the blocks share a picture column until then; a peak is a\n//        local maximum over ±ℓ/2 with z ≥ 4 against the admitted offsets' median and 1.4826·MAD; a\n//        recurrence is three or more peaks congruent modulo one spacing Δ within one frame, its\n//        phase the section's start modulo Δ. On music a recurrence is a returning phrase: it is\n//        labelled \"recurrence\", never \"generated\".\n//\n\nimport Foundation\nimport VeilWatermark\n\npublic struct SectionPeak: Codable, Sendable, Equatable {\n    public var offset: Int\n    public var seconds: Double\n    public var similarity: Double\n    public var z: Double\n    public var bitAgreement: Double\n}\n\npublic struct SectionRecurrenceFound: Codable, Sendable, Equatable {\n    public var stepColumns: Int\n    public var stepSeconds: Double\n    public var phaseColumns: Int\n    public var peaks: Int\n}\n\npublic struct SectionReport: Codable, Sendable, Equatable {\n    public var start: Int\n    public var startSeconds: Double\n    public var length: Int\n    public var baselineMedian: Double\n    public var baselineMAD: Double\n    public var peaks: [SectionPeak]\n    public var recurrence: SectionRecurrenceFound?\n}\n\npublic struct SectionSet: Codable, Sendable, Equatable {\n    public var seconds: Double\n    public var length: Int\n    public var sections: [SectionReport]\n    public var withRecurrence: Int\n}\n\npublic enum SectionRecurrence {\n    public static let peakZ = 4.0\n    public static let sectionSeconds: [Double] = [0.5, 1, 1.5, 2]\n\n    public static func scan(_ trace: FragilityTrace, sectionSeconds: [Double] = sectionSeconds) -> [SectionSet] {\n        let t = trace.frameResolution\n        let codes = denseCodes(t)\n        return sectionSeconds.map { seconds in\n            let length = max(1, Int((seconds / t.columnSeconds).rounded()))\n            var sections: [SectionReport] = []\n            var start = 0\n            while start + length <= t.columns {\n                sections.append(section(t, codes: codes, start: start, length: length))\n                start += length\n            }\n            return SectionSet(seconds: seconds, length: length, sections: sections, withRecurrence: sections.filter { $0.recurrence != nil }.count)\n        }\n    }\n\n    /// Four ordinal bits per trace column against the tile 32 frames on, the row below and the two diagonals, masked at the edges.\n    static func denseCodes(_ t: FragilityTrace) -> (bits: [UInt8], masks: [UInt8]) {\n        let ts = WarpConstants.tileSize\n        var bits = [UInt8](repeating: 0, count: t.rows * t.columns), masks = bits\n        for r in 0..<t.rows {\n            for f in 0..<t.columns {\n                let v = t.fr(row: r, column: f)\n                for (k, (dr, df)) in [(0, ts), (1, 0), (1, ts), (-1, ts)].enumerated() {\n                    let nr = r + dr, nf = f + df\n                    guard nr >= 0, nr < t.rows, nf >= 0, nf < t.columns else { continue }\n                    masks[r * t.columns + f] |= 1 << k\n                    if v > t.fr(row: nr, column: nf) { bits[r * t.columns + f] |= 1 << k }\n                }\n            }\n        }\n        return (bits, masks)\n    }\n\n    static func section(_ t: FragilityTrace, codes: (bits: [UInt8], masks: [UInt8]), start a: Int, length l: Int) -> SectionReport {\n        let rows = t.rows, columns = t.columns, ts = WarpConstants.tileSize\n        // The section's block, standardized once.\n        var block = [Double](repeating: 0, count: rows * l)\n        var meanA = 0.0\n        for r in 0..<rows { for j in 0..<l { let v = Double(t.fr(row: r, column: a + j)); block[r * l + j] = v; meanA += v } }\n        meanA /= Double(rows * l)\n        var varA = 0.0\n        for i in block.indices { block[i] -= meanA; varA += block[i] * block[i] }\n        let n = Double(rows * l)\n        var similarity = [Double](repeating: .nan, count: columns - l + 1)\n        var agreement = [Double](repeating: .nan, count: columns - l + 1)\n        for o in 0...(columns - l) where abs(o - a) >= l + ts {\n            var meanB = 0.0\n            for r in 0..<rows { for j in 0..<l { meanB += Double(t.fr(row: r, column: o + j)) } }\n            meanB /= n\n            var cov = 0.0, varB = 0.0\n            var compared = 0, agreed = 0\n            for r in 0..<rows {\n                for j in 0..<l {\n                    let b = Double(t.fr(row: r, column: o + j)) - meanB\n                    cov += block[r * l + j] * b\n                    varB += b * b\n                    let i = r * columns + a + j, k = r * columns + o + j\n                    let m = codes.masks[i] & codes.masks[k]\n                    compared += m.nonzeroBitCount\n                    agreed += (~(codes.bits[i] ^ codes.bits[k]) & m).nonzeroBitCount\n                }\n            }\n            similarity[o] = varA > 0 && varB > 0 ? cov / (varA * varB).squareRoot() : 0\n            agreement[o] = compared > 0 ? Double(agreed) / Double(compared) : .nan\n        }\n        let admitted = similarity.filter { !$0.isNaN }\n        let (median, mad) = PeriodicityScan.robust(admitted)\n        let scale = mad > 0 ? 1.4826 * mad : .infinity\n        var peaks: [SectionPeak] = []\n        let half = max(1, l / 2)\n        for o in similarity.indices where !similarity[o].isNaN {\n            let z = scale.isFinite ? (similarity[o] - median) / scale : 0\n            guard z >= peakZ else { continue }\n            var isMaximum = true\n            for p in max(0, o - half)...min(similarity.count - 1, o + half) where p != o && !similarity[p].isNaN && similarity[p] > similarity[o] { isMaximum = false; break }\n            guard isMaximum else { continue }\n            peaks.append(SectionPeak(offset: o, seconds: Double(o) * t.columnSeconds, similarity: similarity[o], z: z, bitAgreement: agreement[o]))\n        }\n        return SectionReport(start: a, startSeconds: Double(a) * t.columnSeconds, length: l, baselineMedian: median, baselineMAD: mad, peaks: peaks,\n                             recurrence: recurrence(start: a, peaks: peaks.map(\\.offset), columnSeconds: t.columnSeconds))\n    }\n\n    /// Three or more peaks congruent modulo one spacing, within one column.\n    static func recurrence(start a: Int, peaks: [Int], columnSeconds: Double) -> SectionRecurrenceFound? {\n        let offsets = ([a] + peaks).sorted()\n        guard offsets.count >= 3 else { return nil }\n        var spacings = Set<Int>()\n        for i in 1..<offsets.count { spacings.insert(offsets[i] - offsets[i - 1]) }\n        var best: SectionRecurrenceFound? = nil\n        for step in spacings.sorted() where step > 1 {\n            let count = offsets.filter { o in\n                let residue = ((o - a) % step + step) % step\n                return residue <= 1 || residue >= step - 1\n            }.count\n            if count >= 3, best == nil || count > best!.peaks {\n                best = SectionRecurrenceFound(stepColumns: step, stepSeconds: Double(step) * columnSeconds, phaseColumns: ((a % step) + step) % step, peaks: count)\n            }\n        }\n        return best\n    }\n}\n"},{"path":"Sources/VeilGardeAudio/Research/TimePhaseStudy.swift","status":"added","lang":"swift","hunks":[[1,0,1,187]],"header":{"lines":[1,16],"target":"VeilGardeAudio","what":[6,9],"pin":[10,15],"in":null,"out":null,"style":"swift"},"marks":[],"first":982,"scopes":[["S","HypothesisRow",null,"public",21,21,[21,58],28,null,-1,0,"a"],["S","TimePhaseFlags",null,"public",30,30,[30,59],35,null,-1,0,"a"],["S","TimePhaseReencode",null,"public",37,37,[37,62],43,null,-1,0,"a"],["S","TimePhaseReport",null,"public",45,45,[45,60],60,null,-1,0,"a"],["S","TimePhaseSummary",null,"public",62,62,[62,50],77,null,-1,0,"a"],["S","Dominant",null,"public",63,63,[63,46],63,null,4,8,"a"],["E","TimePhaseStudy",null,"public",79,79,[79,27],187,null,-1,0,"a",[]],["f","measure",["_","path","kind","profile","sectionSeconds","subHop","reencode"],"public static",92,92,[93,131],117,[91,91],6,0,"a"],["f","periodicities",["_","probes"],"public static",120,120,[120,121],124,[119,119],6,0,"a"],["f","summarize",["_"],"public static",126,126,[126,83],151,null,6,0,"a"],["f","bin",["_"],"",127,127,[127,42],138,null,9,4,"a"],["f","figure",["_","t","e"],"public static",154,154,[154,102],186,[153,153],6,0,"a"],["f","scaled",["_"],"",159,159,[159,57],162,null,11,4,"a"],["f","paint",["_","columns","y0"],"",163,163,[163,61],172,null,11,4,"a"],["f","curve",["_","y0"],"",175,175,[175,46],182,null,11,4,"a"]],"old":"","new":"//\n//  TimePhaseStudy.swift\n//  VeilGardeAudio\n//  SPDX-License-Identifier: GPL-3.0-only\n//\n//  WHAT: The time-phase study of one clip and of a corpus: the trace, the sections' recurrences,\n//        the periodicity of T and of E, the flags the hypothesis rows read, the AAC re-encode's\n//        trace beside the original for the codec-frame row, a figure, and the corpus summary. The\n//        hypothesis rows are data here so the record names them as the rules do.\n//  PIN:  Rules fixed before any run (ledger decision-148, rules.md in the study's folder). A clip\n//        is flagged \"stepUnder20ms\" when E has a confirmed fundamental under 20 ms, \"codecFrame\"\n//        when the re-encode's E has a confirmed line within 5% of the codec frame's period where\n//        the original's z there is under 2. The codec frame is 1024 samples at the clip's native rate,\n//        in the profile's columns. No row claims generated against recorded sound: there is no\n//        recorded sound from hardware to compare against this phase.\n//\n\nimport Foundation\nimport VeilGardeCore\n\npublic struct HypothesisRow: Codable, Sendable, Equatable {\n    public var id: String\n    public var clips: String\n    public var expected: String\n    public var instrument: String\n    public var confirmedWhen: String\n    public var refutedWhen: String\n}\n\npublic struct TimePhaseFlags: Codable, Sendable, Equatable {\n    public var flat: Bool\n    public var recurrence: Bool\n    public var stepUnder20ms: Bool\n    public var codecFrame: Bool?\n}\n\npublic struct TimePhaseReencode: Codable, Sendable, Equatable {\n    public var usedKilobitsPerSecond: Int\n    public var codecLagColumns: Double\n    public var zOriginalAtCodecLag: Double\n    public var zReencodeAtCodecLag: Double\n    public var periodicityE: Periodicity\n}\n\npublic struct TimePhaseReport: Codable, Sendable, Equatable {\n    public var path: String\n    public var kind: String\n    public var profile: SpectrogramProfile.Record\n    public var nativeRate: Double\n    public var seconds: Double\n    public var frames: Int\n    public var subHop: Int\n    public var traceColumns: Int\n    public var sections: [SectionSet]\n    public var periodicityT: Periodicity\n    public var periodicityE: Periodicity\n    public var flags: TimePhaseFlags\n    public var reencode: TimePhaseReencode?\n    public var elapsed: Double\n}\n\npublic struct TimePhaseSummary: Codable, Sendable {\n    public struct Dominant: Codable, Sendable { public var path: String; public var lag: Int?; public var milliseconds: Double?; public var z: Double? }\n    public var clips: Int\n    public var flat: Int\n    public var withRecurrence: Int\n    public var stepUnder20ms: Int\n    public var codecFrame: Int?\n    public var reencoded: Int\n    /// The confirmed fundamentals' lags per clip, the raw material every hypothesis row is judged on.\n    public var confirmedLagsE: [String: [Int]]\n    public var confirmedLagsT: [String: [Int]]\n    public var dominantE: [Dominant]\n    public var dominantT: [Dominant]\n    /// E's dominant steps binned in milliseconds: \"<10\", \"10-20\", \"20-50\", \"50-100\", \"100-300\", \"300-1000\", \">1000\", \"none\".\n    public var histogramE: [String: Int]\n}\n\npublic enum TimePhaseStudy {\n    public static let rows: [HypothesisRow] = [\n        HypothesisRow(id: \"P1\", clips: \"musicLike seeds 1–5, 12 s, music\", expected: \"the note grid: 0.25 s = 21.5 frames, multiples 43, 65, 86\", instrument: \"E, frame\", confirmedWhen: \"a confirmed peak at 21 or 22 in ≥ 4 of 5\", refutedWhen: \"fewer\"),\n        HypothesisRow(id: \"P2\", clips: \"the same, in T\", expected: \"the same, attenuated to 0.21\", instrument: \"T\", confirmedWhen: \"confirmed in T, so T suffices under a tile\", refutedWhen: \"not confirmed: E is required\"),\n        HypothesisRow(id: \"N1\", clips: \"whiteNoise seeds 1–5, silence, tone, both profiles\", expected: \"nothing\", instrument: \"T and E\", confirmedWhen: \"no confirmed peak in any\", refutedWhen: \"any confirmed peak: the z ≥ 4 rule is reported miscalibrated, not raised\"),\n        HypothesisRow(id: \"B1\", clips: \"10 s excerpts of the masters, AAC 128 kb/s against the original\", expected: \"the codec frame: 1024 samples at 48 kHz, 7.35 quarter steps, 21.3 ms\", instrument: \"E, quarter\", confirmedWhen: \"a confirmed peak at 7–8 in the re-encode, z < 2 there in the original, in ≥ 50% of excerpts\", refutedWhen: \"absent\"),\n        HypothesisRow(id: \"S1\", clips: \"the 56 say utterances, speech\", expected: \"a synthesis step of 8–20 ms, 2–5 quarter steps (a guess about the voices)\", instrument: \"E, quarter\", confirmedWhen: \"confirmed in ≥ 50%\", refutedWhen: \"< 25%\"),\n        HypothesisRow(id: \"S2\", clips: \"the same, weaker\", expected: \"unit or frame edges at 5–10 ms; 10 ms = 2.5 steps is testable, 5 ms is not\", instrument: \"E, quarter\", confirmedWhen: \"confirmed at 2–3 steps in ≥ 30%\", refutedWhen: \"nowhere; 5 ms left open\"),\n        HypothesisRow(id: \"M1\", clips: \"the 3 masters in 30 s segments\", expected: \"the beat: a dominant step of 300–1000 ms, consistent within a master\", instrument: \"T and E, frame\", confirmedWhen: \"the median dominant step per master in that range, MAD ≤ 2 frames\", refutedWhen: \"otherwise\"),\n        HypothesisRow(id: \"M2\", clips: \"the same, 10 s excerpts\", expected: \"nothing confirmed under 20 ms\", instrument: \"E, quarter\", confirmedWhen: \"none in ≥ 80% of excerpts\", refutedWhen: \"≥ 2 masters show one in ≥ 50%: post-processing bleed, reported as such\"),\n    ]\n\n    /// One clip's report, and its trace for the figure.\n    public static func measure(_ clip: AudioClip, path: String, kind: String, profile: SpectrogramProfile, sectionSeconds: [Double] = SectionRecurrence.sectionSeconds,\n                               subHop: Int = 1, reencode: Bool = false) throws -> (report: TimePhaseReport, trace: FragilityTrace) {\n        let started = Date()\n        let trace = try FragilityTrace.measure(clip, profile: profile, subHop: subHop)\n        let sections = SectionRecurrence.scan(trace, sectionSeconds: sectionSeconds)\n        let codecColumns = 1024 * profile.sampleRate / clip.sampleRate / trace.columnSamples\n        let (t, e) = periodicities(trace, probes: reencode ? [codecColumns] : [])\n        var flags = TimePhaseFlags(flat: t.flat && e.flat, recurrence: sections.contains { $0.withRecurrence > 0 },\n                                   stepUnder20ms: e.steps.contains { $0.milliseconds < 20 }, codecFrame: nil)\n        var reencodeReport: TimePhaseReencode? = nil\n        if reencode {\n            let aac = try AudioConverting.aacRoundTrip(clip, kilobitsPerSecond: profile.aacKilobitsPerSecond)\n            let lag = SignalAlignment.lag(of: aac.clip.mono, against: clip.mono)\n            let realigned = AudioClip(sampleRate: clip.sampleRate, mono: SignalAlignment.aligned(aac.clip.mono, by: lag, length: clip.frames))\n            let (_, eAAC) = periodicities(try FragilityTrace.measure(realigned, profile: profile, subHop: subHop), probes: [codecColumns])\n            let zOriginal = e.probes.first?.z ?? 0, zReencode = eAAC.probes.first?.z ?? 0\n            let confirmedNear = eAAC.peaks.contains { $0.confirmed && abs($0.period - codecColumns) <= max(1, 0.05 * codecColumns) }\n            flags.codecFrame = confirmedNear && zOriginal < PeriodicityScan.harmonicZ\n            reencodeReport = TimePhaseReencode(usedKilobitsPerSecond: aac.usedKilobitsPerSecond, codecLagColumns: codecColumns, zOriginalAtCodecLag: zOriginal,\n                                               zReencodeAtCodecLag: zReencode, periodicityE: eAAC)\n        }\n        let report = TimePhaseReport(path: path, kind: kind, profile: profile.record, nativeRate: clip.sampleRate, seconds: clip.seconds, frames: trace.frames, subHop: subHop,\n                                     traceColumns: trace.columns, sections: sections, periodicityT: t, periodicityE: e, flags: flags, reencode: reencodeReport,\n                                     elapsed: Date().timeIntervalSince(started))\n        return (report, trace)\n    }\n\n    /// T's periodicity from periods of 32 frames and E's from 2 steps; `probes` are lags whose z is wanted.\n    public static func periodicities(_ trace: FragilityTrace, probes: [Double] = []) -> (t: Periodicity, e: Periodicity) {\n        let t = PeriodicityScan.scan((0..<trace.rows).map(trace.frRow), lagMin: 32 * trace.subHop, columnSeconds: trace.columnSeconds, columnSamples: trace.columnSamples, probes: probes)\n        let e = PeriodicityScan.scan((0..<trace.rows).map(trace.residualRow), lagMin: 2, columnSeconds: trace.columnSeconds, columnSamples: trace.columnSamples, probes: probes)\n        return (t, e)\n    }\n\n    public static func summarize(_ reports: [TimePhaseReport]) -> TimePhaseSummary {\n        func bin(_ ms: Double?) -> String {\n            guard let ms else { return \"none\" }\n            switch ms {\n            case ..<10: return \"<10\"\n            case ..<20: return \"10-20\"\n            case ..<50: return \"20-50\"\n            case ..<100: return \"50-100\"\n            case ..<300: return \"100-300\"\n            case ..<1000: return \"300-1000\"\n            default: return \">1000\"\n            }\n        }\n        var histogram: [String: Int] = [:]\n        for r in reports { histogram[bin(r.periodicityE.dominant?.milliseconds), default: 0] += 1 }\n        let reencoded = reports.filter { $0.reencode != nil }\n        return TimePhaseSummary(\n            clips: reports.count, flat: reports.filter(\\.flags.flat).count, withRecurrence: reports.filter(\\.flags.recurrence).count,\n            stepUnder20ms: reports.filter(\\.flags.stepUnder20ms).count, codecFrame: reencoded.isEmpty ? nil : reencoded.filter { $0.flags.codecFrame == true }.count,\n            reencoded: reencoded.count,\n            confirmedLagsE: Dictionary(uniqueKeysWithValues: reports.map { ($0.path, $0.periodicityE.steps.map(\\.lag)) }),\n            confirmedLagsT: Dictionary(uniqueKeysWithValues: reports.map { ($0.path, $0.periodicityT.steps.map(\\.lag)) }),\n            dominantE: reports.map { .init(path: $0.path, lag: $0.periodicityE.dominant?.lag, milliseconds: $0.periodicityE.dominant?.milliseconds, z: $0.periodicityE.dominant?.z) },\n            dominantT: reports.map { .init(path: $0.path, lag: $0.periodicityT.dominant?.lag, milliseconds: $0.periodicityT.dominant?.milliseconds, z: $0.periodicityT.dominant?.z) },\n            histogramE: histogram)\n    }\n\n    /// A figure: T with each tile row 8 px tall, E beneath it, and the pooled autocorrelations of T and E as strips, each panel scaled to its own range.\n    public static func figure(_ trace: FragilityTrace, t: Periodicity, e: Periodicity) throws -> Data {\n        let width = trace.pictureColumns\n        let rowHeight = 8, strip = 48, gap = 4\n        let height = trace.rows * rowHeight * 2 + strip * 2 + gap * 3\n        var gray = [UInt8](repeating: 0, count: width * height)\n        func scaled(_ values: [Float]) -> (Float, Float) {\n            let finite = values.filter(\\.isFinite)\n            return (finite.min() ?? 0, finite.max() ?? 1)\n        }\n        func paint(_ values: [Float], columns: Int, y0: Int) {\n            let (lo, hi) = scaled(values)\n            let span = hi > lo ? hi - lo : 1\n            for r in 0..<trace.rows {\n                for x in 0..<min(columns, width) {\n                    let level = UInt8(max(0, min(255, ((values[r * columns + x] - lo) / span * 255).rounded())))\n                    for dy in 0..<rowHeight { gray[(y0 + r * rowHeight + dy) * width + x] = level }\n                }\n            }\n        }\n        paint(trace.fr, columns: trace.columns, y0: 0)\n        paint(trace.residual, columns: trace.pictureColumns, y0: trace.rows * rowHeight + gap)\n        func curve(_ p: Periodicity, y0: Int) {\n            guard let lo = p.curve.min(), let hi = p.curve.max(), hi > lo else { return }\n            for (i, v) in p.curve.enumerated() {\n                let x = i * (width - 1) / max(1, p.curve.count - 1)\n                let h = Int(((v - lo) / (hi - lo) * Double(strip - 1)).rounded())\n                for dy in 0...h { gray[(y0 + strip - 1 - dy) * width + x] = 255 }\n            }\n        }\n        curve(t, y0: trace.rows * rowHeight * 2 + gap * 2)\n        curve(e, y0: trace.rows * rowHeight * 2 + gap * 3 + strip)\n        return try SpectrogramImage.pngData(gray: gray, width: width, height: height)\n    }\n}\n"},{"path":"Sources/VeilGardeAudio/Spectrogram/AnalysisSignal.swift","status":"added","lang":"swift","hunks":[[1,0,1,49]],"header":{"lines":[1,13],"target":"VeilGardeAudio","what":[6,7],"pin":[8,12],"in":null,"out":null,"style":"swift"},"marks":[],"first":997,"scopes":[["S","AnalysisSignal",null,"public",18,18,[18,50],49,null,-1,0,"a"],["i","init",["profile","samples"],"public",22,22,[22,64],25,null,0,0,"a"],["i","init",["_","profile"],"public",27,27,[27,71],35,null,0,0,"a"],["v","frames",null,"public",37,37,[37,27],37,null,0,8,"a"],["v","seconds",null,"public",38,38,[38,31],38,null,0,8,"a"],["v","rmsDBFS",null,"public",40,40,[40,31],45,null,0,0,"a"],["f","clip",[],"public",48,48,[48,36],48,[47,47],0,8,"a"]],"old":"","new":"//\n//  AnalysisSignal.swift\n//  VeilGardeAudio\n//  SPDX-License-Identifier: GPL-3.0-only\n//\n//  WHAT: The carrier's canonical input: one channel of Double samples at the profile's rate, made\n//        from any clip; and the way back to a clip for writing.\n//  PIN:  Mixdown (the channels' mean), then AudioConverting's resampler when the clip's rate is\n//        not the profile's; identity otherwise, so a cut of a clip at the profile's rate holds\n//        exactly its source's samples and its interior frames equal the source's. No mean is\n//        removed: a DC offset would shift source and cut alike, and the picture drops the DC bin.\n//        A clip over the duration cap is refused here, before any memory is spent on it.\n//\n\nimport Foundation\nimport VeilGardeCore\n\npublic struct AnalysisSignal: Sendable, Equatable {\n    public let profile: SpectrogramProfile\n    public var samples: [Double]\n\n    public init(profile: SpectrogramProfile, samples: [Double]) {\n        self.profile = profile\n        self.samples = samples\n    }\n\n    public init(_ clip: AudioClip, profile: SpectrogramProfile) throws {\n        guard clip.seconds <= SpectrogramProfile.maximumSeconds else {\n            throw VeilGardeFailure.usage(String(format: \"the clip is %.0f s long; the carrier takes up to %.0f s\", clip.seconds, SpectrogramProfile.maximumSeconds),\n                                         hint: \"cut a window with `veilgarde audio export --start --duration`\")\n        }\n        let resampled = try AudioConverting.resampled(clip.mono, from: clip.sampleRate, to: profile.sampleRate)\n        self.profile = profile\n        self.samples = resampled.map(Double.init)\n    }\n\n    public var frames: Int { profile.frameCount(samples: samples.count) }\n    public var seconds: Double { Double(samples.count) / profile.sampleRate }\n\n    public var rmsDBFS: Double {\n        var sum = 0.0\n        for x in samples { sum += x * x }\n        guard !samples.isEmpty, sum > 0 else { return -.infinity }\n        return 10 * log10(sum / Double(samples.count))\n    }\n\n    /// A mono clip at the profile's rate.\n    public func clip() -> AudioClip { AudioClip(sampleRate: profile.sampleRate, mono: samples.map(Float.init)) }\n}\n"},{"path":"Sources/VeilGardeAudio/Spectrogram/Framing.swift","status":"added","lang":"swift","hunks":[[1,0,1,49]],"header":{"lines":[1,13],"target":"VeilGardeAudio","what":[6,7],"pin":[8,12],"in":null,"out":null,"style":"swift"},"marks":[],"first":1004,"scopes":[["E","Framing",null,"public",17,17,[17,20],49,null,-1,0,"a",[]],["f","frames",["_"],"public static",19,19,[19,89],35,[18,18],0,0,"a"],["f","windowSquareSum",["frames","profile"],"public static",38,38,[38,101],48,[37,37],0,0,"a"]],"old":"","new":"//\n//  Framing.swift\n//  VeilGardeAudio\n//  SPDX-License-Identifier: GPL-3.0-only\n//\n//  WHAT: A signal cut into windowed frames for the FFT, and the per-sample window-square sum the\n//        inverse divides by.\n//  PIN:  Centre padding of N/2 zeros on both sides, so frames = 1 + ⌊L / hop⌋ and frame t is\n//        centred on sample t · hop. Zeros, not a reflection, so a frame depends only on real\n//        samples inside its span, and a cut's interior frames equal its source's. Frames are\n//        row-major Float, count × N, each sample multiplied by the periodic Hann in Double and\n//        rounded once.\n//\n\nimport Foundation\n\npublic enum Framing {\n    /// The windowed frames of `signal`, row-major count × N.\n    public static func frames(_ signal: AnalysisSignal) -> (values: [Float], count: Int) {\n        let p = signal.profile\n        let N = p.fftSize, H = p.hop, pad = p.padding, L = signal.samples.count\n        let count = p.frameCount(samples: L)\n        let w = p.window\n        var out = [Float](repeating: 0, count: count * N)\n        signal.samples.withUnsafeBufferPointer { x in\n            for t in 0..<count {\n                let start = t * H - pad\n                let base = t * N\n                let n0 = max(0, -start), n1 = min(N, L - start)\n                guard n0 < n1 else { continue }\n                for n in n0..<n1 { out[base + n] = Float(x[start + n] * w[n]) }\n            }\n        }\n        return (out, count)\n    }\n\n    /// Σ over the existing frames of w² at every padded sample, length (count − 1) · hop + N.\n    public static func windowSquareSum(frames count: Int, profile p: SpectrogramProfile) -> [Double] {\n        let N = p.fftSize, H = p.hop\n        guard count > 0 else { return [] }\n        let w2 = p.window.map { $0 * $0 }\n        var sum = [Double](repeating: 0, count: (count - 1) * H + N)\n        for t in 0..<count {\n            let base = t * H\n            for n in 0..<N { sum[base + n] += w2[n] }\n        }\n        return sum\n    }\n}\n"},{"path":"Sources/VeilGardeAudio/Spectrogram/GrayMapping.swift","status":"added","lang":"swift","hunks":[[1,0,1,39]],"header":{"lines":[1,14],"target":"VeilGardeAudio","what":[6,7],"pin":[8,13],"in":null,"out":null,"style":"swift"},"marks":[],"first":1007,"scopes":[["E","GrayMapping",null,"public",18,18,[18,24],39,null,-1,0,"a",[]],["v","span",null,"public static",19,19,[19,35],19,null,0,8,"a"],["f","decibels",["magnitude","profile"],"public static",22,22,[22,90],24,[21,21],0,0,"a"],["f","level",["magnitude","profile"],"public static",26,26,[26,86],31,null,0,0,"a"],["f","magnitude",["level","profile"],"public static",34,34,[34,86],38,[33,33],0,0,"a"]],"old":"","new":"//\n//  GrayMapping.swift\n//  VeilGardeAudio\n//  SPDX-License-Identifier: GPL-3.0-only\n//\n//  WHAT: A magnitude to one of 256 grey levels and back: the mapping that makes a sound a picture\n//        the warp round trip can read.\n//  PIN:  dB = 20·log10(|X| / (N/4)), so a full-scale sine's peak bin reads 0 dBFS; level =\n//        round(255 · (dB + 96) / 96) to nearest, away from zero on a tie, clamped to 255, so one\n//        level is 0.376 dB; a magnitude of zero, or one under the floor plus half a step, is level\n//        0, and level 0 dequantizes to zero. Absolute dBFS, never the clip's own peak: a cut's\n//        pixels must equal its source's, and an additive constant survives the warps only when it\n//        is a whole number of levels (−6.02 dB is 15.99 of them). 0 dBFS → 255, −6.02 dB → 239.\n//\n\nimport Foundation\n\npublic enum GrayMapping {\n    public static var span: Double { SpectrogramProfile.ceilingDB - SpectrogramProfile.floorDB }\n\n    /// `magnitude` in dBFS under the profile's reference; −infinity at zero.\n    public static func decibels(magnitude: Double, profile: SpectrogramProfile) -> Double {\n        magnitude > 0 ? 20 * log10(magnitude / profile.magnitudeReference) : -.infinity\n    }\n\n    public static func level(magnitude: Double, profile: SpectrogramProfile) -> UInt8 {\n        guard magnitude > 0 else { return 0 }\n        let x = (decibels(magnitude: magnitude, profile: profile) - SpectrogramProfile.floorDB) / span * Double(SpectrogramProfile.levels)\n        if x < 0.5 { return 0 }\n        return UInt8(min(Double(SpectrogramProfile.levels), x.rounded(.toNearestOrAwayFromZero)))\n    }\n\n    /// The magnitude a level stands for: the centre of its step; zero for level 0.\n    public static func magnitude(level: UInt8, profile: SpectrogramProfile) -> Double {\n        guard level > 0 else { return 0 }\n        let dB = SpectrogramProfile.floorDB + Double(level) / Double(SpectrogramProfile.levels) * span\n        return profile.magnitudeReference * pow(10, dB / 20)\n    }\n}\n"},{"path":"Sources/VeilGardeAudio/Spectrogram/SignalAlignment.swift","status":"added","lang":"swift","hunks":[[1,0,1,54]],"header":{"lines":[1,11],"target":"VeilGardeAudio","what":[6,8],"pin":[9,10],"in":null,"out":null,"style":"swift"},"marks":[],"first":1012,"scopes":[["E","SignalAlignment",null,"public",17,17,[17,28],54,null,-1,0,"a",[]],["f","lag",["of","against","maximumLag"],"public static",21,21,[21,109],43,[20,20],0,0,"a"],["f","aligned",["_","by","length"],"public static",46,46,[46,90],53,[45,45],0,0,"a"]],"old":"","new":"//\n//  SignalAlignment.swift\n//  VeilGardeAudio\n//  SPDX-License-Identifier: GPL-3.0-only\n//\n//  WHAT: The integer lag between two signals, by cross-correlation through the FFT on the GPU, and\n//        a signal shifted by that lag: how the acceptance verifies that a codec's decode came back\n//        time-aligned, and corrects it when it did not.\n//  PIN:  The correlation of the first 2²⁰ samples at most, zero-padded to a power of two; the lag\n//        is the argmax over ±maximumLag, positive when the candidate is late. Empty input gives 0.\n//\n\nimport Foundation\nimport MLX\nimport VeilGardeLens\n\npublic enum SignalAlignment {\n    public static let maximumSamples = 1 << 20\n\n    /// The lag by which `candidate` is late against `reference`: candidate[i + lag] ≈ reference[i].\n    public static func lag(of candidate: [Float], against reference: [Float], maximumLag: Int = 4096) -> Int {\n        guard !candidate.isEmpty, !reference.isEmpty, maximumLag > 0 else { return 0 }\n        defer { LensRuntime.releaseMemory() }\n        let a = Array(reference.prefix(maximumSamples)), b = Array(candidate.prefix(maximumSamples))\n        let needed = max(a.count, b.count) + maximumLag\n        var size = 1\n        while size < needed { size <<= 1 }\n        let spectrumA = MLXFFT.rfft(MLXArray(a + [Float](repeating: 0, count: size - a.count)))\n        let spectrumB = MLXFFT.rfft(MLXArray(b + [Float](repeating: 0, count: size - b.count)))\n        let correlation = MLXFFT.irfft(spectrumB * spectrumA.conjugate(), n: size)\n        MLX.eval(correlation)\n        let c = correlation.asArray(Float.self)\n        var best = 0\n        var bestValue = -Float.infinity\n        for k in -maximumLag...maximumLag {\n            let v = c[(k + size) % size]\n            if v > bestValue {\n                bestValue = v\n                best = k\n            }\n        }\n        return best\n    }\n\n    /// `candidate` advanced by `lag` and cut or zero-padded to `length`.\n    public static func aligned(_ candidate: [Float], by lag: Int, length: Int) -> [Float] {\n        var out = [Float](repeating: 0, count: max(0, length))\n        for i in out.indices {\n            let j = i + lag\n            if j >= 0 && j < candidate.count { out[i] = candidate[j] }\n        }\n        return out\n    }\n}\n"},{"path":"Sources/VeilGardeAudio/Spectrogram/Spectrogram.swift","status":"added","lang":"swift","hunks":[[1,0,1,120]],"header":{"lines":[1,17],"target":"VeilGardeAudio","what":[6,9],"pin":[10,16],"in":null,"out":null,"style":"swift"},"marks":[],"first":1015,"scopes":[["S","Spectrogram",null,"public",23,23,[23,47],120,null,-1,0,"a"],["i","init",["_","framesPerEval"],"public",34,34,[34,97],58,[33,33],0,0,"a"],["f","magnitude",["frame","bin"],"public",60,60,[60,58],63,null,0,0,"a"],["f","inverse",[],"public",66,66,[66,44],93,[65,65],0,0,"a"],["f","replacingMagnitudes",["with"],"public",96,96,[96,81],119,[95,95],0,0,"a"]],"old":"","new":"//\n//  Spectrogram.swift\n//  VeilGardeAudio\n//  SPDX-License-Identifier: GPL-3.0-only\n//\n//  WHAT: The complex short-time Fourier transform of an analysis signal and its exact inverse, the\n//        two places the carrier's arithmetic runs on the GPU; and the same transform with its\n//        magnitudes replaced by a picture's, the original phase kept, for the way back from the\n//        8-bit picture.\n//  PIN:  Frigate's MLXFFT.rfft and irfft on float32 frames, in chunks of framesPerEval; the real\n//        and imaginary parts come back as Float and everything else is Double on the CPU. The\n//        inverse is the windowed overlap-add divided by the per-sample window-square sum over the\n//        frames that exist (1.5 away from the ends), then the padding trimmed, so a signal comes\n//        back to float precision. From a picture, each complex value is scaled by the dequantized\n//        magnitude over its own; zero stays zero, and the DC bin, which the picture does not hold,\n//        is set to zero. The chunk size does not change a value (SpectrogramTests).\n//\n\nimport Foundation\nimport MLX\nimport VeilGardeLens\n\npublic struct Spectrogram: Sendable, Equatable {\n    public let profile: SpectrogramProfile\n    public let frames: Int\n    /// N/2 + 1 complex bins per frame; the picture keeps bins 1…N/2.\n    public let bins: Int\n    public let sampleCount: Int\n    /// Row-major frames × bins.\n    public var real: [Float]\n    public var imaginary: [Float]\n\n    /// The transform of `signal`, `framesPerEval` frames an MLX call (the profile's budget unless a test asks).\n    public init(_ signal: AnalysisSignal, framesPerEval: Int = SpectrogramProfile.framesPerEval) {\n        defer { LensRuntime.releaseMemory() }\n        let p = signal.profile\n        let N = p.fftSize, B = N / 2 + 1\n        let (values, count) = Framing.frames(signal)\n        var re = [Float](repeating: 0, count: count * B)\n        var im = re\n        var t0 = 0\n        while t0 < count {\n            let t1 = min(t0 + max(1, framesPerEval), count)\n            let chunk = MLXArray(Array(values[(t0 * N)..<(t1 * N)]), [t1 - t0, N])\n            let x = MLXFFT.rfft(chunk, axis: 1)\n            let r = x.realPart(), i = x.imaginaryPart()\n            MLX.eval(r, i)\n            re.replaceSubrange((t0 * B)..<(t1 * B), with: r.asArray(Float.self))\n            im.replaceSubrange((t0 * B)..<(t1 * B), with: i.asArray(Float.self))\n            t0 = t1\n        }\n        profile = p\n        frames = count\n        bins = B\n        sampleCount = signal.samples.count\n        real = re\n        imaginary = im\n    }\n\n    public func magnitude(frame: Int, bin: Int) -> Double {\n        let k = frame * bins + bin\n        return hypot(Double(real[k]), Double(imaginary[k]))\n    }\n\n    /// The signal back, to float precision.\n    public func inverse() -> AnalysisSignal {\n        defer { LensRuntime.releaseMemory() }\n        let N = profile.fftSize, H = profile.hop, B = bins, pad = profile.padding, count = frames\n        guard count > 0 else { return AnalysisSignal(profile: profile, samples: []) }\n        let w = profile.window\n        var acc = [Double](repeating: 0, count: (count - 1) * H + N)\n        var t0 = 0\n        while t0 < count {\n            let t1 = min(t0 + SpectrogramProfile.framesPerEval, count)\n            let r = MLXArray(Array(real[(t0 * B)..<(t1 * B)]), [t1 - t0, B])\n            let i = MLXArray(Array(imaginary[(t0 * B)..<(t1 * B)]), [t1 - t0, B])\n            let y = MLXFFT.irfft(r + i.asImaginary(), n: N, axis: 1)\n            MLX.eval(y)\n            let f = y.asArray(Float.self)\n            for t in t0..<t1 {\n                let base = (t - t0) * N, j0 = t * H\n                for n in 0..<N { acc[j0 + n] += Double(f[base + n]) * w[n] }\n            }\n            t0 = t1\n        }\n        let wss = Framing.windowSquareSum(frames: count, profile: profile)\n        var out = [Double](repeating: 0, count: sampleCount)\n        for s in 0..<sampleCount {\n            let j = s + pad\n            out[s] = wss[j] > 0 ? acc[j] / wss[j] : 0\n        }\n        return AnalysisSignal(profile: profile, samples: out)\n    }\n\n    /// The same phase under the picture's magnitudes.\n    public func replacingMagnitudes(with image: SpectrogramImage) -> Spectrogram {\n        precondition(image.width == frames && image.height == bins - 1, \"the picture is \\(image.width)×\\(image.height), the spectrogram \\(frames)×\\(bins - 1)\")\n        var copy = self\n        let B = bins\n        for t in 0..<frames {\n            copy.real[t * B] = 0\n            copy.imaginary[t * B] = 0\n            for bin in 1..<B {\n                let k = t * B + bin\n                let re = Double(real[k]), im = Double(imaginary[k])\n                let m = hypot(re, im)\n                let level = image.level(frame: t, bin: bin)\n                if m == 0 || level == 0 {\n                    copy.real[k] = 0\n                    copy.imaginary[k] = 0\n                    continue\n                }\n                let scale = GrayMapping.magnitude(level: level, profile: profile) / m\n                copy.real[k] = Float(re * scale)\n                copy.imaginary[k] = Float(im * scale)\n            }\n        }\n        return copy\n    }\n}\n"},{"path":"Sources/VeilGardeAudio/Spectrogram/SpectrogramImage.swift","status":"added","lang":"swift","hunks":[[1,0,1,114]],"header":{"lines":[1,15],"target":"VeilGardeAudio","what":[6,9],"pin":[10,14],"in":null,"out":null,"style":"swift"},"marks":[],"first":1020,"scopes":[["S","SpectrogramImage",null,"public",24,24,[24,52],114,null,-1,0,"a"],["i","init",["_"],"public",33,33,[33,44],47,null,0,0,"a"],["i","init",["profile","width","gray"],"public",49,49,[49,79],57,null,0,0,"a"],["i","init",["cgImage","profile"],"public",60,60,[60,70],66,[59,59],0,0,"a"],["f","level",["frame","bin"],"public",69,69,[69,53],69,[68,68],0,8,"a"],["v","cgImage",null,"public",72,72,[72,32],74,[71,71],0,0,"a"],["f","cgImage",["gray","width","height"],"public static",77,77,[77,89],93,[76,76],0,0,"a"],["f","pngData",[],"public",95,95,[95,41],95,null,0,8,"a"],["f","pngData",["gray","width","height"],"public static",97,97,[97,86],106,null,0,0,"a"],["v","floorShare",null,"public",109,109,[109,34],109,[108,108],0,8,"a"],["v","ceilingShare",null,"public",111,111,[111,36],111,[110,110],0,8,"a"],["v","graySHA256",null,"public",113,113,[113,34],113,[112,112],0,8,"a"]],"old":"","new":"//\n//  SpectrogramImage.swift\n//  VeilGardeAudio\n//  SPDX-License-Identifier: GPL-3.0-only\n//\n//  WHAT: The picture the watermark signs: the spectrogram's grey levels, one byte a pixel, frames\n//        left to right and the highest kept bin in the top row; the CGImage the lens reads from it\n//        unchanged; the way back from such an image; a PNG of it; and the shares of pixels at the\n//        floor and at the ceiling.\n//  PIN:  Row r holds bin bins − r, so bin 1 is the bottom row; the DC bin is not drawn. The CGImage\n//        is an 8-bit DeviceRGB noneSkipLast bitmap with R = G = B, exactly the context\n//        ImageLoading.rgbPixels draws into, so the lens reads these bytes and ImageCodec.isFlat is\n//        true. The PNG writer lives here through ImageIO: ImageCodec is lossy platform\n//        recompression, and the Lens does not change for the audio carrier.\n//\n\nimport CoreGraphics\nimport Foundation\nimport ImageIO\nimport UniformTypeIdentifiers\nimport VeilGardeCore\nimport VeilGardeLens\n\npublic struct SpectrogramImage: Sendable, Equatable {\n    public let profile: SpectrogramProfile\n    /// Frames.\n    public let width: Int\n    /// The bins kept, 1…N/2.\n    public let height: Int\n    /// Row-major grey levels, row 0 the highest bin.\n    public let gray: [UInt8]\n\n    public init(_ spectrogram: Spectrogram) {\n        profile = spectrogram.profile\n        width = spectrogram.frames\n        height = spectrogram.profile.bins\n        let B = spectrogram.bins\n        var g = [UInt8](repeating: 0, count: width * height)\n        for t in 0..<width {\n            for bin in 1...height {\n                let k = t * B + bin\n                let m = hypot(Double(spectrogram.real[k]), Double(spectrogram.imaginary[k]))\n                g[(height - bin) * width + t] = GrayMapping.level(magnitude: m, profile: profile)\n            }\n        }\n        gray = g\n    }\n\n    public init(profile: SpectrogramProfile, width: Int, gray: [UInt8]) throws {\n        guard width > 0, gray.count == width * profile.bins else {\n            throw VeilGardeFailure.data(\"a \\(profile.name) picture of \\(width) frames holds \\(width * profile.bins) levels, not \\(gray.count)\")\n        }\n        self.profile = profile\n        self.width = width\n        self.height = profile.bins\n        self.gray = gray\n    }\n\n    /// A flat 8-bit RGB image back to its levels (the red channel), for a picture someone saved.\n    public init(cgImage: CGImage, profile: SpectrogramProfile) throws {\n        guard cgImage.height == profile.bins else { throw VeilGardeFailure.data(\"a \\(profile.name) picture is \\(profile.bins) px tall, not \\(cgImage.height)\") }\n        let pixels = try ImageLoading.rgbPixels(cgImage, width: cgImage.width, height: cgImage.height)\n        var g = [UInt8](repeating: 0, count: cgImage.width * cgImage.height)\n        for i in g.indices { g[i] = UInt8(pixels[i * 3]) }\n        try self.init(profile: profile, width: cgImage.width, gray: g)\n    }\n\n    /// The level of `bin` (1…height) at `frame`.\n    public func level(frame: Int, bin: Int) -> UInt8 { gray[(height - bin) * width + frame] }\n\n    /// The bitmap the lens reads unchanged: 8-bit DeviceRGB, no alpha, R = G = B.\n    public var cgImage: CGImage {\n        get throws { try Self.cgImage(gray: gray, width: width, height: height) }\n    }\n\n    /// Any grey plane as that bitmap; the study's figures use it too.\n    public static func cgImage(gray: [UInt8], width: Int, height: Int) throws -> CGImage {\n        guard width > 0, height > 0, gray.count == width * height else { throw VeilGardeFailure.data(\"a \\(width)×\\(height) picture needs \\(width * height) levels, not \\(gray.count)\") }\n        var bytes = [UInt8](repeating: 255, count: width * height * 4)\n        for i in gray.indices {\n            let v = gray[i]\n            bytes[i * 4] = v\n            bytes[i * 4 + 1] = v\n            bytes[i * 4 + 2] = v\n        }\n        let image: CGImage? = bytes.withUnsafeMutableBytes { raw in\n            guard let ctx = CGContext(data: raw.baseAddress, width: width, height: height, bitsPerComponent: 8, bytesPerRow: width * 4,\n                                      space: CGColorSpaceCreateDeviceRGB(), bitmapInfo: CGImageAlphaInfo.noneSkipLast.rawValue) else { return nil }\n            return ctx.makeImage()\n        }\n        guard let image else { throw VeilGardeFailure.internalError(\"cannot make a \\(width)×\\(height) picture\") }\n        return image\n    }\n\n    public func pngData() throws -> Data { try Self.pngData(gray: gray, width: width, height: height) }\n\n    public static func pngData(gray: [UInt8], width: Int, height: Int) throws -> Data {\n        let image = try cgImage(gray: gray, width: width, height: height)\n        let out = NSMutableData()\n        guard let destination = CGImageDestinationCreateWithData(out, UTType.png.identifier as CFString, 1, nil) else {\n            throw VeilGardeFailure.internalError(\"ImageIO has no PNG encoder on this Mac\")\n        }\n        CGImageDestinationAddImage(destination, image, nil)\n        guard CGImageDestinationFinalize(destination) else { throw VeilGardeFailure.internalError(\"the PNG encode failed\") }\n        return out as Data\n    }\n\n    /// The share of pixels at level 0.\n    public var floorShare: Double { Double(gray.reduce(0) { $0 + ($1 == 0 ? 1 : 0) }) / Double(max(1, gray.count)) }\n    /// The share of pixels at level 255.\n    public var ceilingShare: Double { Double(gray.reduce(0) { $0 + ($1 == 255 ? 1 : 0) }) / Double(max(1, gray.count)) }\n    /// The SHA-256 of the levels, the pin a test holds.\n    public var graySHA256: String { ContentHash.sha256Hex(Data(gray)) }\n}\n"},{"path":"Sources/VeilGardeAudio/Spectrogram/SpectrogramProfile.swift","status":"added","lang":"swift","hunks":[[1,0,1,108]],"header":{"lines":[1,19],"target":"VeilGardeAudio","what":[6,10],"pin":[11,18],"in":null,"out":null,"style":"swift"},"marks":[],"first":1032,"scopes":[["S","SpectrogramProfile",null,"public",24,24,[24,63],108,null,-1,0,"a"],["i","init",["name","sampleRate","fftSize","hop","minimumSeconds","aacKilobitsPerSecond"],"public",48,48,[48,125],55,null,0,0,"a"],["v","bins",null,"public",58,58,[58,25],58,[57,57],0,8,"a"],["v","rows",null,"public",60,60,[60,25],60,[59,59],0,8,"a"],["v","padding",null,"public",62,62,[62,28],62,[61,61],0,8,"a"],["v","magnitudeReference",null,"public",64,64,[64,42],64,[63,63],0,8,"a"],["v","window",null,"public",66,66,[66,32],66,[65,65],0,8,"a"],["v","windowSum",null,"public",67,67,[67,33],67,null,0,8,"a"],["v","windowSquareSum",null,"public",68,68,[68,39],68,null,0,8,"a"],["v","tileSeconds",null,"public",70,70,[70,35],70,[69,69],0,8,"a"],["v","tileHertz",null,"public",71,71,[71,33],71,null,0,8,"a"],["f","frameCount",["samples"],"public",74,74,[74,48],74,[73,73],0,8,"a"],["f","seconds",["column"],"public",76,76,[76,47],76,[75,75],0,8,"a"],["f","bits",["columns"],"public",78,78,[78,42],82,[77,77],0,0,"a"],["f","named",["_"],"public static",84,84,[84,68],84,null,0,8,"a"],["f","inferred",["rows"],"public static",86,86,[86,66],86,[85,85],0,8,"a"],["S","Record",null,"public",89,89,[89,55],102,[88,88],0,0,"a"],["v","record",null,"public",104,104,[104,30],107,null,0,0,"a"]],"old":"","new":"//\n//  SpectrogramProfile.swift\n//  VeilGardeAudio\n//  SPDX-License-Identifier: GPL-3.0-only\n//\n//  WHAT: Every constant of the picture a clip becomes, in one place: the two profiles the owner\n//        fixed on 2026-11-08, music at 44.1 kHz and speech at 16 kHz, each with its FFT size and\n//        hop; and what both share: the floor and ceiling in dBFS, the 255 levels, the magnitude\n//        reference, the frame budget, the duration cap, and the minimum a clip needs to be admitted\n//        to the acceptance.\n//  PIN:  Rules fixed before any number was measured (ledger decision-139). Music: 44,100 Hz mono,\n//        N 2048, hop 512, bins 1…1024, so the picture is 1024 px tall and 32 tile rows; speech:\n//        16,000 Hz, N 1024, hop 256, bins 1…512, 16 tile rows. Periodic Hann, so Σw = N/2 and\n//        Σw² = 3N/8, and the four overlapping copies sum to 1.5 at every interior sample. A\n//        full-scale sine's peak bin is N/4, the reference for 0 dBFS; the floor is −96 dBFS. For R\n//        tile rows and c columns the grid measures R(c−1) + (R−1)c + 2(R−1)(c−1) bits: 125c − 94 for\n//        music, 61c − 46 for speech. The profiles are to be merged after enough research (the owner,\n//        2026-11-08).\n//\n\nimport Foundation\nimport VeilWatermark\n\npublic struct SpectrogramProfile: Sendable, Equatable, Codable {\n    public let name: String\n    public let sampleRate: Double\n    public let fftSize: Int\n    public let hop: Int\n    /// The acceptance admits clips at least this long: a half cut then keeps ≥ 256 bits with margin.\n    public let minimumSeconds: Double\n    /// The re-encode's AAC bit rate, the JPEG q75 analog.\n    public let aacKilobitsPerSecond: Int\n\n    public static let floorDB: Double = -96\n    public static let ceilingDB: Double = 0\n    public static let levels = 255\n    /// STFT frames evaluated per MLX call.\n    public static let framesPerEval = 4096\n    /// Clips longer than this are refused in v1 (memory: a 10-minute music clip is about 0.6 GB at peak).\n    public static let maximumSeconds: Double = 600\n    /// The acceptance skips clips quieter than this.\n    public static let minimumRMSDBFS: Double = -40\n\n    public static let music = SpectrogramProfile(name: \"music\", sampleRate: 44_100, fftSize: 2048, hop: 512, minimumSeconds: 4, aacKilobitsPerSecond: 128)\n    public static let speech = SpectrogramProfile(name: \"speech\", sampleRate: 16_000, fftSize: 1024, hop: 256, minimumSeconds: 8, aacKilobitsPerSecond: 64)\n    public static let all: [SpectrogramProfile] = [music, speech]\n\n    public init(name: String, sampleRate: Double, fftSize: Int, hop: Int, minimumSeconds: Double, aacKilobitsPerSecond: Int) {\n        self.name = name\n        self.sampleRate = sampleRate\n        self.fftSize = fftSize\n        self.hop = hop\n        self.minimumSeconds = minimumSeconds\n        self.aacKilobitsPerSecond = aacKilobitsPerSecond\n    }\n\n    /// The bins the picture keeps, 1…N/2: its height in pixels.\n    public var bins: Int { fftSize / 2 }\n    /// Tile rows of the picture.\n    public var rows: Int { bins / WarpConstants.tileSize }\n    /// Zeros on each side of the signal, so every sample is covered by four frames.\n    public var padding: Int { fftSize / 2 }\n    /// A full-scale sine's peak bin under the periodic Hann: 0 dBFS.\n    public var magnitudeReference: Double { Double(fftSize) / 4 }\n    /// The periodic Hann window, built in Double (MLX's hanning is the symmetric form).\n    public var window: [Double] { (0..<fftSize).map { 0.5 - 0.5 * cos(2 * Double.pi * Double($0) / Double(fftSize)) } }\n    public var windowSum: Double { Double(fftSize) / 2 }\n    public var windowSquareSum: Double { 3 * Double(fftSize) / 8 }\n    /// One tile's span in time and in frequency.\n    public var tileSeconds: Double { Double(hop * WarpConstants.tileSize) / sampleRate }\n    public var tileHertz: Double { sampleRate / Double(fftSize) * Double(WarpConstants.tileSize) }\n\n    /// Frames of a signal of `samples`: 1 + ⌊samples / hop⌋ under the centre padding.\n    public func frameCount(samples: Int) -> Int { samples < 0 ? 0 : 1 + samples / hop }\n    /// The time a picture column stands for.\n    public func seconds(column: Int) -> Double { Double(column) * Double(hop) / sampleRate }\n    /// The bits a full-height grid of `columns` tile columns measures.\n    public func bits(columns: Int) -> Int {\n        guard columns > 0, rows > 0 else { return 0 }\n        let R = rows, c = columns\n        return R * (c - 1) + (R - 1) * c + 2 * (R - 1) * (c - 1)\n    }\n\n    public static func named(_ name: String) -> SpectrogramProfile? { all.first { $0.name == name } }\n    /// The profile a signature was made under, from its tile rows: 32 is music, 16 is speech.\n    public static func inferred(rows: Int) -> SpectrogramProfile? { all.first { $0.rows == rows } }\n\n    /// The constants as data, for reports.\n    public struct Record: Codable, Sendable, Equatable {\n        public var name: String\n        public var sampleRate: Double\n        public var fftSize: Int\n        public var hop: Int\n        public var bins: Int\n        public var rows: Int\n        public var floorDB: Double\n        public var ceilingDB: Double\n        public var levels: Int\n        public var minimumSeconds: Double\n        public var maximumSeconds: Double\n        public var aacKilobitsPerSecond: Int\n    }\n\n    public var record: Record {\n        Record(name: name, sampleRate: sampleRate, fftSize: fftSize, hop: hop, bins: bins, rows: rows, floorDB: Self.floorDB, ceilingDB: Self.ceilingDB,\n               levels: Self.levels, minimumSeconds: minimumSeconds, maximumSeconds: Self.maximumSeconds, aacKilobitsPerSecond: aacKilobitsPerSecond)\n    }\n}\n"},{"path":"Sources/VeilGardeAudio/VeilGardeAudio.swift","status":"added","lang":"swift","hunks":[[1,0,1,11]],"header":{"lines":[1,9],"target":"VeilGardeAudio","what":[6,8],"pin":null,"in":null,"out":null,"style":"swift"},"marks":[],"first":1050,"scopes":[],"old":"","new":"//\n//  VeilGardeAudio.swift\n//  VeilGardeAudio\n//  SPDX-License-Identifier: GPL-3.0-only\n//\n//  WHAT: The watermark's second carrier: a clip becomes its spectrogram picture, the picture is\n//        signed and matched by the watermark unchanged, and the picture goes back to audio. Nothing\n//        is written into the sound. It re-exports VeilWatermark, which re-exports the Lens and Core.\n//\n\n@_exported import VeilWatermark\n"},{"path":"Sources/VeilGardeAudio/Watermark/AudioRoundTrip.swift","status":"added","lang":"swift","hunks":[[1,0,1,83]],"header":{"lines":[1,16],"target":"VeilGardeAudio","what":[6,9],"pin":[10,15],"in":null,"out":null,"style":"swift"},"marks":[],"first":1050,"scopes":[["S","AudioRoundTripMetrics",null,"public",20,20,[20,66],66,null,-1,0,"a"],["i","init",["samples","snrDB","maxAbsoluteError","logSpectralDeviationDB"],"public",26,26,[26,103],31,null,0,0,"a"],["f","measure",["reference","candidate","referenceSpectrogram"],"public static",34,34,[34,152],47,[33,33],0,0,"a"],["f","logSpectralDeviation",["_","_"],"public static",50,50,[50,90],65,[49,49],0,0,"a"],["E","AudioRoundTrip",null,"public",68,68,[68,27],83,null,-1,0,"a",[]],["f","exact",["_"],"public static",70,70,[70,115],74,[69,69],4,0,"a"],["f","throughImage",["_"],"public static",77,77,[77,147],82,[76,76],4,0,"a"]],"old":"","new":"//\n//  AudioRoundTrip.swift\n//  VeilGardeAudio\n//  SPDX-License-Identifier: GPL-3.0-only\n//\n//  WHAT: The picture back to sound, two ways, and how far the sound moved: the exact path, the\n//        untouched complex transform inverted; and the image path, the magnitudes dequantized from\n//        the 8-bit picture under the original phase. The metrics: SNR, the largest sample error and\n//        the log-spectral deviation.\n//  PIN:  SNR = 10·log10(Σx² / Σ(x − y)²) over the shorter length, infinite when the error is zero;\n//        the deviation is the RMS over frames and bins of 20·log10(|Y| / |X|) where both sit at or\n//        above the floor's magnitude. The bars fixed before measuring: exact ≥ 90 dB and max error\n//        ≤ 1e-4 (float32 FFTs give about 110 dB); image ≥ 30 dB and deviation ≤ 0.2 dB (a 0.376 dB\n//        step gives about 38 dB). The name logSpectralDeviation stays clear of Frigate's\n//        spectralDistance.\n//\n\nimport Foundation\n\npublic struct AudioRoundTripMetrics: Codable, Sendable, Equatable {\n    public var samples: Int\n    public var snrDB: Double\n    public var maxAbsoluteError: Double\n    public var logSpectralDeviationDB: Double\n\n    public init(samples: Int, snrDB: Double, maxAbsoluteError: Double, logSpectralDeviationDB: Double) {\n        self.samples = samples\n        self.snrDB = snrDB\n        self.maxAbsoluteError = maxAbsoluteError\n        self.logSpectralDeviationDB = logSpectralDeviationDB\n    }\n\n    /// `candidate` against `reference`; the reference's spectrogram is reused when given.\n    public static func measure(reference: AnalysisSignal, candidate: AnalysisSignal, referenceSpectrogram: Spectrogram? = nil) -> AudioRoundTripMetrics {\n        let n = min(reference.samples.count, candidate.samples.count)\n        var signal = 0.0, noise = 0.0, worst = 0.0\n        for i in 0..<n {\n            let x = reference.samples[i], d = candidate.samples[i] - x\n            signal += x * x\n            noise += d * d\n            worst = max(worst, abs(d))\n        }\n        let snr: Double = noise == 0 ? .infinity : (signal == 0 ? -.infinity : 10 * log10(signal / noise))\n        let a = referenceSpectrogram ?? Spectrogram(reference)\n        let b = Spectrogram(candidate)\n        return AudioRoundTripMetrics(samples: n, snrDB: snr, maxAbsoluteError: worst, logSpectralDeviationDB: logSpectralDeviation(a, b))\n    }\n\n    /// The RMS of the dB difference over the bins both spectrograms hold at or above the floor.\n    public static func logSpectralDeviation(_ a: Spectrogram, _ b: Spectrogram) -> Double {\n        let frames = min(a.frames, b.frames), B = min(a.bins, b.bins)\n        let floor = a.profile.magnitudeReference * pow(10, SpectrogramProfile.floorDB / 20)\n        var sum = 0.0\n        var count = 0\n        for t in 0..<frames {\n            for k in 1..<B {\n                let ma = a.magnitude(frame: t, bin: k), mb = b.magnitude(frame: t, bin: k)\n                guard ma >= floor, mb >= floor else { continue }\n                let d = 20 * log10(mb / ma)\n                sum += d * d\n                count += 1\n            }\n        }\n        return count > 0 ? (sum / Double(count)).squareRoot() : 0\n    }\n}\n\npublic enum AudioRoundTrip {\n    /// The exact path: the complex transform and back.\n    public static func exact(_ signal: AnalysisSignal) -> (signal: AnalysisSignal, metrics: AudioRoundTripMetrics) {\n        let spectrogram = Spectrogram(signal)\n        let back = spectrogram.inverse()\n        return (back, .measure(reference: signal, candidate: back, referenceSpectrogram: spectrogram))\n    }\n\n    /// The image path: the picture's magnitudes under the original phase, and back.\n    public static func throughImage(_ signal: AnalysisSignal) -> (signal: AnalysisSignal, image: SpectrogramImage, metrics: AudioRoundTripMetrics) {\n        let spectrogram = Spectrogram(signal)\n        let image = SpectrogramImage(spectrogram)\n        let back = spectrogram.replacingMagnitudes(with: image).inverse()\n        return (back, image, .measure(reference: signal, candidate: back, referenceSpectrogram: spectrogram))\n    }\n}\n"},{"path":"Sources/VeilGardeAudio/Watermark/AudioWatermark.swift","status":"added","lang":"swift","hunks":[[1,0,1,129]],"header":{"lines":[1,16],"target":"VeilGardeAudio","what":[6,8],"pin":[9,15],"in":null,"out":null,"style":"swift"},"marks":[],"first":1057,"scopes":[["S","AudioMatchResult",null,"public",24,24,[24,61],71,null,-1,0,"a"],["i","init",["result","profile","frames"],"public",33,33,[33,79],39,null,0,0,"a"],["v","matched",null,"public",41,41,[41,29],41,null,0,8,"a"],["v","column",null,"public",43,43,[43,27],43,[42,42],0,8,"a"],["v","seconds",null,"public",45,45,[45,31],45,[44,44],0,8,"a"],["v","frequencyRows",null,"public",47,47,[47,34],47,[46,46],0,8,"a"],["E","CodingKeys",null,"",49,49,[49,39],49,null,0,8,"a",[]],["i","init",["from"],"public",51,51,[51,46],58,null,0,0,"a"],["f","encode",["to"],"public",60,60,[60,51],70,null,0,0,"a"],["E","AudioWatermark",null,"public",73,73,[73,27],129,null,-1,0,"a",[]],["f","picture",["_","profile"],"public static",75,75,[75,106],77,[74,74],9,0,"a"],["f","sign",["_","profile"],"public static",80,80,[80,105],82,[79,79],9,0,"a"],["f","sign",["_"],"public static",84,84,[84,84],86,null,9,0,"a"],["f","fragility",["_"],"public static",89,89,[89,84],92,[88,88],9,0,"a"],["f","fragility",["_","profile"],"public static",94,94,[94,105],96,null,9,0,"a"],["f","phaseCodes",["_","phases"],"public static",99,99,[99,158],103,[98,98],9,0,"a"],["f","match",["_","against","profile","options"],"public static",106,106,[107,90],110,[105,105],9,0,"a"],["f","match",["_","against","options"],"public static",112,112,[112,156],115,null,9,0,"a"],["f","profile",["of"],"public static",118,118,[118,94],123,[117,117],9,0,"a"],["f","expectedColumn",["startSample","nativeRate","profile"],"public static",126,126,[126,112],128,[125,125],9,0,"a"]],"old":"","new":"//\n//  AudioWatermark.swift\n//  VeilGardeAudio\n//  SPDX-License-Identifier: GPL-3.0-only\n//\n//  WHAT: The thin door from a clip to the watermark: its picture, its signature by Watermark.sign,\n//        its fragility grid, and a match of a clip against a signature with the grid phases read\n//        along time only; the match carries the offset in seconds.\n//  PIN:  Nothing in VeilWatermark changes or is bypassed: the signature is Watermark.sign of the\n//        picture's bitmap, a vw1 no different from an image's. Matching reads\n//        NativePlane.fragility(originX: px, originY: 0) for px in the phases, 0, 8, 16 and 24 by\n//        default, four grid reads instead of sixteen, since a cut keeps every frequency row; the\n//        thresholds are the watermark's own, 0.75 over 256 bits. A clip is signed at any length\n//        with one full tile column, as an image is; only the acceptance admits by duration. The\n//        profile of a signature is read off its tile rows, 32 for music and 16 for speech.\n//\n\nimport CoreGraphics\nimport Foundation\nimport VeilGardeCore\nimport VeilGardeLens\nimport VeilWatermark\n\npublic struct AudioMatchResult: Codable, Sendable, Equatable {\n    /// The watermark's own result, offsets in tiles and the phase in pixels.\n    public var result: MatchResult\n    public var profile: String\n    /// The probe picture's width in frames.\n    public var frames: Int\n    public var hop: Int\n    public var sampleRate: Double\n\n    public init(result: MatchResult, profile: SpectrogramProfile, frames: Int) {\n        self.result = result\n        self.profile = profile.name\n        self.frames = frames\n        self.hop = profile.hop\n        self.sampleRate = profile.sampleRate\n    }\n\n    public var matched: Bool { result.matched }\n    /// The signed picture's column the probe's first frame stands on.\n    public var column: Int { result.pixelX }\n    /// That column in seconds of the signed clip.\n    public var seconds: Double { Double(result.pixelX) * Double(hop) / sampleRate }\n    /// The frequency offset in tile rows; 0 for a true match.\n    public var frequencyRows: Int { result.offsetY }\n\n    enum CodingKeys: String, CodingKey { case result, profile, frames, hop, sampleRate, column, seconds, frequencyRows }\n\n    public init(from decoder: Decoder) throws {\n        let c = try decoder.container(keyedBy: CodingKeys.self)\n        result = try c.decode(MatchResult.self, forKey: .result)\n        profile = try c.decode(String.self, forKey: .profile)\n        frames = try c.decode(Int.self, forKey: .frames)\n        hop = try c.decode(Int.self, forKey: .hop)\n        sampleRate = try c.decode(Double.self, forKey: .sampleRate)\n    }\n\n    public func encode(to encoder: Encoder) throws {\n        var c = encoder.container(keyedBy: CodingKeys.self)\n        try c.encode(result, forKey: .result)\n        try c.encode(profile, forKey: .profile)\n        try c.encode(frames, forKey: .frames)\n        try c.encode(hop, forKey: .hop)\n        try c.encode(sampleRate, forKey: .sampleRate)\n        try c.encode(column, forKey: .column)\n        try c.encode(seconds, forKey: .seconds)\n        try c.encode(frequencyRows, forKey: .frequencyRows)\n    }\n}\n\npublic enum AudioWatermark {\n    /// The picture of `clip` under `profile`.\n    public static func picture(_ clip: AudioClip, profile: SpectrogramProfile) throws -> SpectrogramImage {\n        SpectrogramImage(Spectrogram(try AnalysisSignal(clip, profile: profile)))\n    }\n\n    /// `clip`'s signature: the watermark's own, read off its picture.\n    public static func sign(_ clip: AudioClip, profile: SpectrogramProfile) throws -> WatermarkSignature {\n        try sign(try picture(clip, profile: profile))\n    }\n\n    public static func sign(_ image: SpectrogramImage) throws -> WatermarkSignature {\n        try Watermark.sign(try image.cgImage)\n    }\n\n    /// Every full tile's fragility rate of the picture, at phase (0, 0).\n    public static func fragility(_ image: SpectrogramImage) throws -> FragilityGrid {\n        defer { LensRuntime.releaseMemory() }\n        return try NativePlane(try image.cgImage).fragility()\n    }\n\n    public static func fragility(_ clip: AudioClip, profile: SpectrogramProfile) throws -> FragilityGrid {\n        try fragility(try picture(clip, profile: profile))\n    }\n\n    /// The picture's tile codes at each time phase, the frequency phase 0.\n    public static func phaseCodes(_ image: SpectrogramImage, phases: [Int] = MatchOptions.default.phases) throws -> [(px: Int, py: Int, codes: TileCodeGrid)] {\n        defer { LensRuntime.releaseMemory() }\n        let plane = try NativePlane(try image.cgImage)\n        return phases.map { px in (px, 0, TileCodeGrid(plane.fragility(originX: px, originY: 0))) }\n    }\n\n    /// Where `clip` sits on `signature`; the profile is the signature's own unless given.\n    public static func match(_ clip: AudioClip, against signature: WatermarkSignature, profile: SpectrogramProfile? = nil,\n                             options: MatchOptions = .default) throws -> AudioMatchResult {\n        let p = try profile ?? self.profile(of: signature)\n        return try match(try picture(clip, profile: p), against: signature, options: options)\n    }\n\n    public static func match(_ image: SpectrogramImage, against signature: WatermarkSignature, options: MatchOptions = .default) throws -> AudioMatchResult {\n        let result = Watermark.match(codes: try phaseCodes(image, phases: options.phases), against: signature, options: options)\n        return AudioMatchResult(result: result, profile: image.profile, frames: image.width)\n    }\n\n    /// The profile a signature was made under, from its tile rows.\n    public static func profile(of signature: WatermarkSignature) throws -> SpectrogramProfile {\n        guard let p = SpectrogramProfile.inferred(rows: signature.rows) else {\n            throw VeilGardeFailure.data(\"a signature of \\(signature.rows) tile rows fits no audio profile\", hint: \"music pictures have 32 tile rows, speech 16\")\n        }\n        return p\n    }\n\n    /// The signed picture's column a cut starting at `startSample` of a clip at `nativeRate` begins on.\n    public static func expectedColumn(startSample: Int, nativeRate: Double, profile: SpectrogramProfile) -> Int {\n        Int((Double(startSample) / nativeRate * profile.sampleRate / Double(profile.hop)).rounded())\n    }\n}\n"}]};
